html body #app .cart-head .cart-checkall{color:#16a34a}
html body #app .cart-head .cart-clear{color:#ef4444}
html body #app .cart-ico-vendor{color:#2563eb!important}
html body #app .cart-ico-sum{color:#f97316!important}
html body #app .cart-ico-del{color:#8b5cf6!important}
html body #app .cart-item .cart-remove,html body #app .cart-item .cart-remove i{color:#ef4444!important;background:transparent!important}
/* order form: coloured delivery / location icons */
