html body #app .hscroll,html body #app .grid{filter:none!important}
/* bottom-sheet drawers (filters + chat actions); big spread shadow = backdrop */
html body #app .browse-filter-panel:not(.hidden),html body #app .vendors-filters-panel:not(.hidden),html body #app .messages-more-menu:not(.hidden){position:fixed!important;left:0!important;right:0!important;top:auto!important;bottom:0!important;width:auto!important;max-width:none!important;max-height:78vh;overflow:auto;margin:0!important;border-radius:22px 22px 0 0!important;padding:1rem 1rem calc(1.2rem + env(safe-area-inset-bottom))!important;z-index:9000!important;background:var(--card)!important;border:0!important;box-shadow:0 0 0 100vmax rgba(0,0,0,.5)!important;animation:none}
html body #app .lm-sheet-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:.6rem}
html body #app .lm-sheet-head .lm-x{width:34px;height:34px;border-radius:50%;border:0;background:color-mix(in srgb,var(--text) 8%,transparent);color:var(--text);cursor:pointer}
html body #app .messages-more-menu:not(.hidden) .ms-item{width:100%;padding:.85rem .5rem;text-align:left}
/* browse filter: icon only, slim search */
html body #app .browse-filter-trigger,html body #app .browse-filter-trigger.active{width:40px!important;min-width:40px!important;height:40px!important;padding:0!important;border-radius:50%!important;background:transparent!important;border:1px solid var(--border)!important;color:var(--text)!important;box-shadow:none!important}
html body #app .browse-filter-trigger .browse-filter-chevron{display:none!important}
html body #app .browse-filter-toolbar #searchInput{height:40px!important;min-height:0!important;padding-top:0!important;padding-bottom:0!important}
/* orders history icon / profile edit pencil */
html body #app .orders-history-btn,html body #app .vendor-profile-edit-btn{width:40px;height:40px;padding:0!important;border-radius:50%!important;display:inline-flex;align-items:center;justify-content:center}
/* splash footer brand */
#levromartSplash .lv-sp-foot{--sp-foot:#8a8f98!important;color:#8a8f98!important}
#levromartSplash .lv-sp-foot img.lv-sp-foot-logo{box-sizing:content-box;background:#fff!important;border-radius:50%!important;padding:6px;width:28px!important;height:28px!important;box-shadow:0 1px 6px rgba(0,0,0,.12)}
/* leaderboard: flat rows, hairlines */
html body #app .lb-row,html body #app .lb-rank-row,html body #app .lb-item{background:transparent!important;box-shadow:none!important;border:0!important;border-radius:0!important;border-bottom:1px solid var(--border)!important}
html body #app .support-page-card{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important;border-radius:0!important}
html body #app .lb-list,html body #app .lb-rows{background:transparent!important;border:0!important;box-shadow:none!important;gap:0!important}
/* onboarding + login follow the dark theme */
html[data-splash="dark"]{--lv-ink:#eaf6f0;--lv-muted:#9db3a8;--lv-line:#26332d}
html[data-splash="dark"] .lv-onb,html[data-splash="dark"] #loginModal.lv-auth{color-scheme:dark;background:linear-gradient(180deg,#0d1210 0%,#101a15 55%,#0d1612 100%)!important;color:#eaf6f0}
