html[data-splash="dark"] #loginModal.lv-auth :is(.lv-card,.lv-field,.lv-form,.lv-social,.lv-oauth,.lv-btn-alt,.lv-ghost){background:#141d18!important;color:#eaf6f0!important;border-color:#2a3a32!important}
html[data-splash="dark"] .lv-onb :is(.lv-ghost,.lv-skip){color:#c5d6cd!important}
html[data-splash="dark"] .lv-bgfx i{border-color:rgba(63,185,127,.14);background:rgba(63,185,127,.07)}
@media (prefers-color-scheme:dark){
html[data-splash="auto"]{--lv-ink:#eaf6f0;--lv-muted:#9db3a8;--lv-line:#26332d}
html[data-splash="auto"] .lv-onb,html[data-splash="auto"] #loginModal.lv-auth{color-scheme:dark;background:linear-gradient(180deg,#0d1210 0%,#101a15 55%,#0d1612 100%)!important;color:#eaf6f0}
html[data-splash="auto"] #loginModal.lv-auth :is(input,select,textarea){background:#16201b!important;color:#eaf6f0!important;border-color:#2a3a32!important}
html[data-splash="auto"] #loginModal.lv-auth :is(.lv-card,.lv-field,.lv-form,.lv-social,.lv-oauth,.lv-btn-alt,.lv-ghost){background:#141d18!important;color:#eaf6f0!important;border-color:#2a3a32!important}
html[data-splash="auto"] .lv-onb :is(.lv-ghost,.lv-skip){color:#c5d6cd!important}
}
#levromartSplash .lv-sp-foot svg.lv-sp-foot-logo{width:34px!important;height:34px!important;background:none!important;box-shadow:none!important;padding:0!important;border-radius:0!important;color:#8a8f98;flex:none}
html[data-splash="dark"] #levromartSplash .lv-sp-foot{color:#8b97a0!important}
html body #app .cart-vendor-head,html body #app .cart-vendor-head span{color:var(--text)!important}
html body #app .cart-head .cart-back{order:0}
html body #app .cart-head .cart-checkall{order:3;color:#16a34a}
html body #app .cart-head .cart-page-title{order:1}
html body #app .cart-head .cart-clear{order:2}
.coa-ico{background:color-mix(in srgb,#16a34a 14%,transparent)!important;color:#16a34a!important}
.cc-confirm.coa-ok{background:#16a34a!important;border-color:#16a34a!important;color:#fff!important}
#levromartSplash .lv-sp-foot{gap:.1rem!important}
#levromartSplash .lv-sp-foot svg.lv-sp-foot-logo{margin-right:-2px}
/* section icons: modern gradient tiles */
html body #app .section-title > i:first-child,html body #app .section-title > span > i:first-child{width:30px;height:30px;border-radius:10px;display:inline-grid;place-items:center;font-size:.85rem;color:#fff!important;margin-right:.5rem;vertical-align:middle;background:linear-gradient(135deg,#34d399,#059669);box-shadow:0 4px 10px -4px rgba(5,150,105,.55)}
html body #app .section-title i.fa-fire{background:linear-gradient(135deg,#fb923c,#ef4444);box-shadow:0 4px 10px -4px rgba(239,68,68,.55)}
html body #app .section-title i.fa-medal{background:linear-gradient(135deg,#fbbf24,#f97316);box-shadow:0 4px 10px -4px rgba(249,115,22,.55)}
html body #app .section-title i.fa-hand-holding-heart{background:linear-gradient(135deg,#a78bfa,#ec4899);box-shadow:0 4px 10px -4px rgba(168,85,247,.55)}
html body #app .section-title i.fa-box-open{background:linear-gradient(135deg,#38bdf8,#2563eb);box-shadow:0 4px 10px -4px rgba(37,99,235,.55)}
/* login: readable in dark */
html[data-splash="dark"] #loginModal.lv-auth{--lv-muted:#c3d4ca}
html[data-splash="dark"] #loginModal.lv-auth :is(label,.lv-check,.lv-switch,.lv-or){color:#d5e3db}
html[data-splash="dark"] #loginModal.lv-auth :is(a,.lv-link,#lvSwitchLink){color:#5be39a}
@media (prefers-color-scheme:dark){
html[data-splash="auto"] #loginModal.lv-auth{--lv-muted:#c3d4ca}
html[data-splash="auto"] #loginModal.lv-auth :is(label,.lv-check,.lv-switch,.lv-or){color:#d5e3db}
html[data-splash="auto"] #loginModal.lv-auth :is(a,.lv-link,#lvSwitchLink){color:#5be39a}
}
/* service page: flat, rounded, negotiation-style */
html body #app .service-flat{background:transparent!important;border:0!important;box-shadow:none!important;border-radius:0!important;padding:.4rem .2rem!important;margin:0 0 1.2rem!important}
html body #app .service-detail-card .product-detail-media img,html body #app .service-detail-card .product-gallery-main img{border-radius:20px!important;width:100%;max-height:340px;object-fit:cover}
html body #app .service-detail-card .product-detail-media,html body #app .service-detail-card .product-gallery,html body #app .service-detail-card .product-gallery-main{border-radius:20px!important;overflow:hidden;background:transparent!important;border:0!important;box-shadow:none!important}
html body #app .service-vendor-info-block{background:transparent!important;border:0!important;border-top:1px solid var(--border)!important;border-bottom:1px solid var(--border)!important;border-radius:0!important;padding:.8rem 0!important;margin:1rem 0!important}
html body #app .service-vendor-info-head{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important}
html body #app .service-description-block h3,html body #app .service-request-card h3{font-size:1.15rem;margin:.2rem 0 .4rem}
html body #app .service-request-card h3 i{color:#8b5cf6;margin-right:.35rem}
html body #app .svc-price-box{display:flex;align-items:center;justify-content:center;gap:.8rem;margin:.5rem 0 .7rem}
html body #app .svc-step{width:48px;height:48px;border-radius:50%;border:1px solid var(--border);background:transparent;color:var(--text);font-size:1rem;cursor:pointer;flex:none}
html body #app .svc-price-in{display:flex;align-items:center;justify-content:center;gap:.25rem;flex:1;max-width:240px;border-bottom:2px solid var(--border);padding:.2rem 0}
html body #app .svc-price-in span{font-size:1.8rem;font-weight:800;color:var(--muted)}
html body #app .svc-price-in input{border:0!important;background:transparent!important;box-shadow:none!important;font-size:2rem;font-weight:800;text-align:center;width:100%;padding:0!important;color:var(--text)}
html body #app .svc-chips{display:flex;flex-wrap:wrap;gap:.5rem;justify-content:center;margin-bottom:1rem}
html body #app .svc-chip{border:1px solid var(--border);background:transparent;color:var(--text);border-radius:999px;padding:.4rem .9rem;font-weight:700;cursor:pointer}
html body #app .service-request-card textarea{border-radius:16px!important}
html body #app .service-request-card > .btn{width:100%;border-radius:999px;min-height:50px;font-weight:800}
html body #app .service-offer-row{background:transparent!important;border:0!important;border-top:1px solid var(--border)!important;border-radius:0!important;padding:.8rem 0!important;box-shadow:none!important}
/* ---- batch: slim header, flat nav-aware drawers, filters, service cards ---- */
html body > header .header-top-row{min-height:0!important;gap:.5rem!important;padding-top:.25rem!important;padding-bottom:.25rem!important}
html body > header .header-search-row{height:34px!important;min-height:0!important;padding:0 .8rem!important;font-size:.88rem!important}
html body > header .icon-btn,html body > header .avatar-btn,html body > header #loginBtn{width:34px!important;height:34px!important;min-width:0!important;min-height:0!important;font-size:.95rem!important}
html body > header .avatar-btn img,html body > header .avatar-btn .avatar-circle{width:32px!important;height:32px!important}
html body > header{padding-top:calc(env(safe-area-inset-top) + 0px)!important;padding-bottom:.15rem!important}
html body{padding-top:calc(48px + env(safe-area-inset-top))!important}
/* hide bottom nav whenever a drawer is open */
body:has(.browse-filter-panel:not(.hidden)) #bottomNav,body:has(.vendors-filters-panel:not(.hidden)) #bottomNav,body:has(.messages-more-menu:not(.hidden)) #bottomNav,body:has(.cc-backdrop.open) #bottomNav,body:has(.order-filters-panel:not(.hidden)) #bottomNav,body:has(.lm-drawer-open) #bottomNav{transform:translateY(130%)!important;pointer-events:none}
#bottomNav{transition:transform .22s ease}
/* filter buttons: icon only, two lines */
#app .browse-filter-toolbar>.browse-filter-trigger::after{content:none!important;display:none!important}
html body #app .browse-filter-trigger,html body #app .vendors-filters-toggle,html body #app .vd-filter-btn,html body #app .order-filters-trigger{color:var(--text)!important}
html body #app .order-filters-trigger .order-filters-chevron,html body #app .vendors-filters-toggle .vendors-filters-chevron{display:none!important}
.lv-filter-ico{display:block}
/* vendor cards: no dark halo */
html body #app .vc2,html body #app .vc2 *:not(img){box-shadow:none!important}
html body #app .vc2{filter:none!important;background-image:none}
html body #app .hscroll:has(.vc2),html body #app .grid:has(.vc2){filter:none!important;box-shadow:none!important;background:transparent!important}
/* product card spacing */
html body #app .product-card-compact .product-card-compact-footer{margin-top:.5rem!important}
html body #app .product-card-compact h4{margin-bottom:.15rem!important}
/* service cards */
.card-svc-tag{display:inline-flex;align-items:center;gap:.3rem;font-size:.78rem;font-weight:800;color:#7c3aed;background:color-mix(in srgb,#8b5cf6 14%,transparent);padding:.2rem .55rem;border-radius:999px}
.card-svc-cta{color:#7c3aed!important}
.card-svc-cta .product-card-total-label{flex:1;font-weight:800}
/* messages tabs: plain underline tabs */
html body #app .msg-tabs{gap:1.1rem!important;border-bottom:1px solid var(--border)}
html body #app .msg-tabs a,html body #app .msg-tabs a.active{background:transparent!important;border:0!important;box-shadow:none!important;border-radius:0!important;padding:.55rem .1rem!important;color:var(--text-muted,#6b7280)!important;border-bottom:2.5px solid transparent!important}
html body #app .msg-tabs a.active{color:var(--text)!important;border-bottom-color:var(--primary,#16a34a)!important;font-weight:800}
/* service page */
html body #app .service-detail-card .product-gallery-main{aspect-ratio:4/3;background:transparent!important}
html body #app .service-detail-card .product-gallery-main img{width:100%!important;height:100%!important;max-height:none!important;object-fit:cover!important;display:block}
html body #app .service-request-card > .btn{display:flex!important;justify-content:center!important;align-items:center!important;gap:.5rem;text-align:center}
html body > header .header-left,html body > header .header-right{min-height:0!important;height:36px!important}
html body > header .icon-wrap .icon-btn,html body > header #avatarBtn,html body > header #loginBtn,html body > header #notifWrap button,html body > header #messagesWrap button,html body > header #headerCartWrap button{width:36px!important;height:36px!important;min-width:0!important;min-height:0!important;font-size:.98rem!important}
/* ---- batch 4 ---- */
html body #app .pd-step-title i.fa-truck-fast.fa-solid.fa-solid{color:#a78bfa!important}
html body #app label.df-label i.fa-location-dot.fa-solid.fa-solid,html body #app .df-label .fa-location-dot.fa-solid.fa-solid{color:#fbbf24!important}
html body #app .pd-note-box .df-label .lv-pen-ico,html body #app .pd-note-box .df-label svg{color:#60a5fa!important;stroke:#60a5fa!important}
html body #toastStack .toast,html body .toast-stack .toast{border-radius:14px!important;padding:.5rem .85rem!important;font-size:.82rem!important;max-width:min(94vw,30rem)!important;text-align:left}
html body .toast-stack{max-width:min(94vw,30rem)!important}
/* orders filter as a drawer */
html body #app .order-filters-panel:not(.hidden){position:fixed!important;left:0!important;right:0!important;top:auto!important;bottom:0!important;width:auto!important;max-width:none!important;max-height:80vh;overflow:auto;margin:0!important;border-radius:22px 22px 0 0!important;padding:1rem 1rem calc(1.2rem + env(safe-area-inset-bottom))!important;z-index:9000!important;background:var(--card)!important;border:0!important;box-shadow:0 0 0 100vmax rgba(0,0,0,.5)!important}
html body #app .order-filters-trigger,html body #app .order-filters-trigger.has-filters{width:40px!important;height:40px!important;min-width:40px!important;padding:0!important;border-radius:50%!important;background:transparent!important;display:inline-flex!important;align-items:center;justify-content:center}
html body #app .order-filters-trigger span{display:inline-flex}
html body #app .order-filters-trigger .lv-filter-ico{width:20px;height:20px}
/* recent-search lists (orders / browse / vendors) */
html body #app .levro-compact-history-row{display:flex!important;align-items:center;gap:.2rem;position:static!important}
html body #app .levro-compact-history-row .compact-use{flex:1;display:flex!important;align-items:center;gap:.6rem;text-align:left;padding:.65rem .6rem!important;min-height:42px;position:static!important;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
html body #app .levro-compact-history-row .compact-use i{position:static!important;flex:none;color:var(--muted);transform:none!important}
html body #app .levro-compact-history-row .compact-remove{flex:none;width:36px;height:36px;position:static!important}
/* service card tag sits with the icon, above the divider */
html body #app .product-card-meta .card-svc-tag{margin-right:auto}
html body #app .product-card-compact .product-card-compact-footer{margin-top:.8rem!important}
html body #app .product-card-compact h4{margin-bottom:.4rem!important}
/* messages page */
html body #app .msg-tabs-row{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important;border-radius:0!important}
html body #app .msg-search,html body #app .msg-search input{min-height:0!important;height:36px!important;border-radius:12px!important}
html body #app .msg-search input{padding-top:0!important;padding-bottom:0!important}
#messagesWrap:not(.lv-chat-off) .icon-btn>i{animation:none!important}
#messagesWrap:not(.lv-chat-off):has(#messagesDot:not(.hidden)) .icon-btn>i{animation:levroWiggle 2.4s ease-in-out infinite!important}
