/* buttons: content centred */
html body #app .btn:not(.btn-sm):not(.icon-btn){display:inline-flex;align-items:center;justify-content:center;gap:.5rem;text-align:center}
html body #app #postEquipmentRequestBtn,html body #app .vendor-requests-heading-row > .btn{width:100%!important;min-width:0!important}
/* search page: no gap under the (hidden) header */
body:has(.search-page){padding-top:env(safe-area-inset-top)!important}
html body #app .search-page-head{padding-top:.4rem!important;margin-top:0!important}
/* onboarding hero: room to float without being clipped */
.lv-slide-art{padding-top:18px!important;box-sizing:border-box!important}
.lv-hero,.lv-hero-girl{inset:18px 0 0 0!important;height:calc(100% - 18px)!important}
/* section icons: white glyphs, per-section colours */
html body #app .section-title i[class*="fa-"]:first-child{color:#fff!important;-webkit-text-fill-color:#fff!important}
html body #app .section-title > span > i.fa-fire:first-child,html body #app .section-title > i.fa-fire:first-child{background:linear-gradient(135deg,#fdba74,#f97316)!important;box-shadow:0 4px 10px -4px rgba(249,115,22,.6)!important}
html body #app .section-title > span > i.fa-medal:first-child,html body #app .section-title > i.fa-medal:first-child{background:linear-gradient(135deg,#7dd3fc,#2563eb)!important;box-shadow:0 4px 10px -4px rgba(37,99,235,.55)!important}
html body #app .section-title > span > i.fa-shop:first-child,html body #app .section-title > i.fa-shop:first-child{background:linear-gradient(135deg,#6ee7b7,#059669)!important}
/* DM scroll-to-bottom */
.lm-chat-down{position:absolute;left:50%;bottom:5.2rem;transform:translateX(-50%);width:2.6rem;height:2.6rem;border-radius:50%;border:1px solid var(--border);background:color-mix(in srgb,var(--card) 88%,transparent);color:var(--text);display:flex;align-items:center;justify-content:center;z-index:30;box-shadow:0 4px 14px rgba(0,0,0,.18);cursor:pointer}
.lm-chat-down.hidden{display:none}
/* ---- batch 5 ---- */
:root:root:root:root:root:root body #app .product-card-wrap.product-card-compact > .card > .product-card-meta > .card-svc-tag{margin:0 auto 0 0!important;align-self:center!important}
#aiChatFab,#cartFab{touch-action:none!important;-webkit-user-select:none;user-select:none}
