.lf-page{--lf-acc:#16a34a;--lf-acc2:#3fb97f}
.lf-page[data-lf-mode="service"]{--lf-acc:#ea580c;--lf-acc2:#f59e0b}
.lf-page[data-lf-mode="package"]{--lf-acc:#7c3aed;--lf-acc2:#6366f1}
.lf-page .lf-top{background:linear-gradient(135deg,color-mix(in srgb,var(--lf-acc) 14%,var(--bg)),var(--bg) 85%)!important;margin:0 -1rem .5rem;padding:1rem 1rem 1.05rem;border-bottom:0;border-radius:0 0 26px 26px}
.lf-page .lf-back{background:color-mix(in srgb,var(--lf-acc) 16%,transparent)!important;color:var(--lf-acc)!important}
.lf-page .lf-top-copy h3{color:var(--lf-acc)}
