.lf-page[data-lf-mode="service"] .lm-blue{--lm:#f97316}
.lf-page[data-lf-mode="service"] .lm-pink{--lm:#f59e0b}
.lf-page[data-lf-mode="package"] .lm-blue{--lm:#7c3aed}
.lf-page[data-lf-mode="package"] .lm-pink{--lm:#a855f7}

/* round 4: bar sticks to the bottom of the scrolling page (no fixed positioning) */
:root:root body .lf-page>.modal-content{overflow:visible!important;padding-bottom:0!important}
:root:root body .lf-page .lm-actions{position:sticky!important;left:auto!important;right:auto!important;bottom:0!important;top:auto!important;margin:1.2rem -1rem 0!important;padding:.75rem 1rem calc(.75rem + env(safe-area-inset-bottom,0px))!important;z-index:20}

/* round 5: modal-content is the one scroller; bar sticks to its bottom */
