:root:root:root body .lf-var-actions .btn{width:100%;min-height:2.9rem;display:inline-flex;align-items:center;justify-content:center;gap:.45rem;border-radius:999px;font-weight:800;font-size:.92rem;white-space:nowrap;padding:.6rem .5rem;margin:0}
