:root:root:root body #app .product-detail-card .product-gallery-thumbs::-webkit-scrollbar,:root:root:root body #app .product-gallery-varieties-list::-webkit-scrollbar{display:none!important;width:0!important;height:0!important}
.product-detail-card .lv-top-comment-btn i{color:var(--text-muted)}
@media(max-width:720px){:root:root:root body #app .product-detail-card .product-detail-title{padding-right:8.4rem!important}}
/* ---- tour-logo-clean ---- */
/* welcome / install cards: show the app icon once, as a clean rounded tile (no green badge behind it) */
:root:root:root body #tourCallout .install-modal-badge,:root:root:root body #installModal .install-modal-badge:has(#installModalLogo){width:3.6rem!important;height:3.6rem!important;margin:0 auto .55rem!important;padding:0!important;background:none!important;border:0!important;box-shadow:none!important;border-radius:0!important;animation:none!important;overflow:visible!important}
:root:root:root body #tourCallout .install-modal-badge::before,:root:root:root body #tourCallout .install-modal-badge::after{display:none!important}
:root:root:root body #tourLeviLogo,:root:root:root body #installModalLogo{width:3.6rem!important;height:3.6rem!important;border-radius:22%!important;object-fit:cover!important;display:block!important;filter:none!important;-webkit-filter:none!important;background:none!important;box-shadow:0 6px 18px rgba(8,80,50,.28)!important}
/* ---- fin-vendors-tidy ---- */
:root:root body .fin-row{padding:.85rem .1rem}
:root:root body .fin-row-top{display:flex;align-items:center;flex-wrap:nowrap;gap:.5rem}
:root:root body .fin-row-top .fin-name{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.98rem}
.fin-ico{font-size:.95rem;flex:none}.fin-ico.ok{color:var(--text-muted)}.fin-ico.warn{color:#d97706}.fin-ico.bad{color:#dc2626}
.fin-dot{font-size:.55rem;flex:none}.fin-dot.ok{color:#22c55e}
:root:root body .fin-action{margin-left:.2rem;flex:none}
.fin-icbtn{width:2.2rem;height:2.2rem;border-radius:50%;border:1px solid var(--border);background:transparent;color:var(--text-muted);display:inline-flex;align-items:center;justify-content:center;font-size:.85rem;cursor:pointer;padding:0;flex:none}
.fin-icbtn:active{background:color-mix(in srgb,var(--text) 8%,transparent)}
.fin-icbtn.go{border-color:transparent;background:var(--primary);color:#fff}
.fin-icbtn:disabled{opacity:.5}
.fin-meta.fin-grid{display:grid;grid-template-columns:repeat(4,minmax(0,auto));justify-content:space-between;gap:.4rem .6rem;margin-top:.55rem}
.fin-grid>span{display:inline-flex;align-items:center;gap:.35rem;font-size:.8rem;font-weight:600;color:var(--text);white-space:nowrap}
.fin-grid>span i{color:var(--text-muted);font-size:.78rem;width:.9rem;text-align:center}
.fin-grid>span.owed,.fin-grid>span.owed i{color:#d97706}
.fin-due{display:inline-flex;align-items:center;gap:.35rem;font-size:.76rem;font-weight:600;color:var(--text-muted)}
.fin-due.bad{color:#dc2626}.fin-due.warn{color:#d97706}
.flex .fin-icbtn+.fin-icbtn{margin-left:.2rem}
/* ---- fin-vendors-tidy-2 ---- */
:root:root body .fin-row{cursor:pointer}
.fin-nm{flex:1 1 auto;min-width:0;display:flex;align-items:center;gap:.45rem}
.fin-nm .fin-name{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fin-detail{display:none}
.fin-row.open .fin-detail{display:block}
.fin-detail-body{margin-top:.7rem;padding:.7rem .85rem;border-radius:12px;background:color-mix(in srgb,var(--text) 5%,transparent);display:flex;flex-direction:column;gap:.55rem;font-size:.84rem;cursor:default}
.fin-dl{display:flex;align-items:flex-start;gap:.65rem;min-width:0}
.fin-dl>i{width:1rem;text-align:center;color:var(--text-muted);margin-top:.15rem;flex:none}
.fin-dl>span{min-width:0;overflow-wrap:anywhere;font-weight:600}
.fin-dl a{color:var(--text);text-decoration:none}
.fin-wa{display:inline-flex;align-items:center;gap:.4rem;color:#16a34a!important}
.fin-detail-body a:not(.fin-wa){color:var(--primary)}
/* ---- fin-vendors-tidy-3 ---- */
:root:root body .fin-row-top .fin-nm .fin-name{flex:0 1 auto!important}
/* ---- lv-campus-style ---- */
#lvCampus{position:fixed;inset:0;z-index:2147483650;background:var(--bg,#f4f7f5);display:flex;flex-direction:column;animation:lvcIn .22s ease-out;color:var(--text,#0f1d17)}
@keyframes lvcIn{from{opacity:0;transform:translateY(14px)}}
#lvCampus .lvc-top{flex:none;display:flex;align-items:center;gap:.6rem;padding:calc(.7rem + env(safe-area-inset-top,0px)) .9rem .5rem;background:linear-gradient(180deg,color-mix(in srgb,var(--primary,#16a34a) 16%,var(--bg,#f4f7f5)),var(--bg,#f4f7f5))}
#lvCampus .lvc-x{width:2.4rem;height:2.4rem;border-radius:50%;border:0;background:color-mix(in srgb,var(--text,#000) 8%,transparent);color:inherit;font-size:1rem;cursor:pointer;flex:none}
#lvCampus .lvc-title{font-weight:800;font-size:1.12rem;flex:1;min-width:0}
#lvCampus .lvc-skip{border:0;background:transparent;color:var(--text-muted,#667);font:inherit;font-weight:700;cursor:pointer;padding:.4rem .5rem}
#lvCampus .lvc-hero{flex:none;display:flex;align-items:center;gap:.8rem;padding:.2rem 1rem .6rem;background:linear-gradient(180deg,var(--bg,#f4f7f5),var(--bg,#f4f7f5))}
#lvCampus .lvc-mascot{width:74px;height:74px;flex:none;cursor:pointer;-webkit-tap-highlight-color:transparent;animation:lvcBob 3.2s ease-in-out infinite}
@keyframes lvcBob{50%{transform:translateY(-5px)}}
#lvCampus .lvc-mascot.hop{animation:lvcHop .6s ease}
@keyframes lvcHop{30%{transform:translateY(-16px) rotate(-6deg)}60%{transform:translateY(0) rotate(5deg)}100%{transform:none}}
#lvCampus .lvc-eye{transform-origin:center;animation:lvcBlink 4s infinite}
@keyframes lvcBlink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}
#lvCampus .lvc-tassel{transform-origin:62px 22px;animation:lvcSwing 2.4s ease-in-out infinite}
@keyframes lvcSwing{50%{transform:rotate(12deg)}}
#lvCampus .lvc-bubble{position:relative;background:var(--card,#fff);border:1px solid var(--border,#dde5e0);border-radius:16px;padding:.65rem .85rem;font-size:.86rem;font-weight:600;line-height:1.35;box-shadow:0 6px 18px rgba(0,0,0,.06)}
#lvCampus .lvc-bubble:before{content:"";position:absolute;left:-7px;top:22px;width:12px;height:12px;background:inherit;border-left:1px solid var(--border,#dde5e0);border-bottom:1px solid var(--border,#dde5e0);transform:rotate(45deg)}
#lvCampus .lvc-search{flex:none;padding:.2rem 1rem .5rem;background:var(--bg,#f4f7f5)}
#lvCampus .lvc-sbox{display:flex;align-items:center;gap:.6rem;background:var(--card,#fff);border:1.5px solid var(--border,#dde5e0);border-radius:999px;padding:.2rem .4rem .2rem 1rem;box-shadow:0 6px 16px rgba(0,0,0,.05)}
#lvCampus .lvc-sbox i{color:var(--text-muted,#667)}
#lvCampus .lvc-sbox input{flex:1;min-width:0;border:0!important;outline:0!important;background:transparent!important;box-shadow:none!important;font-size:16px;padding:.65rem 0!important;margin:0!important;color:inherit}
#lvCampus input[type=search]::-webkit-search-cancel-button,#lvCampus input[type=search]::-webkit-search-decoration{-webkit-appearance:none;display:none}
#lvCampus .lvc-clear{border:0;background:color-mix(in srgb,var(--text,#000) 9%,transparent);width:1.8rem;height:1.8rem;border-radius:50%;color:inherit;cursor:pointer;display:none}
#lvCampus .lvc-chips{flex:none;display:flex;gap:.45rem;overflow-x:auto;padding:0 1rem .55rem;scrollbar-width:none;background:var(--bg,#f4f7f5)}
#lvCampus .lvc-chips::-webkit-scrollbar{display:none}
#lvCampus .lvc-chip{flex:none;border:1px solid var(--border,#dde5e0);background:var(--card,#fff);color:inherit;border-radius:999px;padding:.42rem .85rem;font:inherit;font-size:.8rem;font-weight:700;cursor:pointer}
#lvCampus .lvc-chip.on{background:var(--primary,#16a34a);border-color:var(--primary,#16a34a);color:#fff}
#lvCampus .lvc-scroll{flex:1;min-height:0;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:.4rem .6rem calc(5.5rem + env(safe-area-inset-bottom,0px))}
#lvCampus .lvc-count{padding:.2rem .5rem .6rem;font-size:.76rem;font-weight:700;letter-spacing:.06em;color:var(--text-muted,#667);text-transform:uppercase}
#lvCampus .lvc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.1rem .3rem}
#lvCampus .lvc-item{display:flex;flex-direction:column;align-items:center;gap:.5rem;border:0;background:transparent;color:inherit;font:inherit;padding:.15rem .1rem;cursor:pointer;-webkit-tap-highlight-color:transparent;min-width:0}
#lvCampus .lvc-logo{position:relative;width:74px;height:74px;border-radius:50%;background:#fff;display:grid;place-items:center;overflow:visible;box-shadow:0 8px 20px rgba(10,60,40,.16),0 0 0 1px rgba(0,0,0,.05);transition:transform .15s}
#lvCampus .lvc-item:active .lvc-logo{transform:scale(.93)}
#lvCampus .lvc-logo img{width:100%;height:100%;border-radius:50%;object-fit:contain;padding:9px;box-sizing:border-box;background:#fff}
#lvCampus .lvc-ini{width:100%;height:100%;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:800;font-size:1.15rem;letter-spacing:.02em}
#lvCampus .lvc-item.sel .lvc-logo{box-shadow:0 0 0 3px var(--primary,#16a34a),0 8px 20px rgba(10,60,40,.2)}
#lvCampus .lvc-tick{position:absolute;right:-2px;bottom:-2px;width:1.4rem;height:1.4rem;border-radius:50%;background:var(--primary,#16a34a);color:#fff;font-size:.65rem;display:none;place-items:center;border:2px solid var(--bg,#f4f7f5)}
#lvCampus .lvc-item.sel .lvc-tick{display:grid}
#lvCampus .lvc-name{font-size:.74rem;font-weight:700;line-height:1.25;text-align:center;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;max-width:100%;word-break:break-word}
#lvCampus .lvc-sub{font-size:.64rem;font-weight:600;color:var(--text-muted,#667);margin-top:-.3rem}
#lvCampus .lvc-empty{text-align:center;padding:2rem 1rem;color:var(--text-muted,#667)}
#lvCampus .lvc-foot{position:absolute;left:0;right:0;bottom:0;padding:.7rem 1rem calc(.8rem + env(safe-area-inset-bottom,0px));background:linear-gradient(0deg,var(--bg,#f4f7f5) 70%,transparent);display:flex;gap:.6rem}
#lvCampus .lvc-foot button{flex:1;border:1.5px solid var(--border,#dde5e0);background:var(--card,#fff);color:inherit;border-radius:14px;padding:.8rem .6rem;font:inherit;font-weight:700;font-size:.86rem;cursor:pointer}
#lvCampus .lvc-foot button.pri{background:var(--primary,#16a34a);border-color:var(--primary,#16a34a);color:#fff}
#lvCampus .lvc-custom{position:absolute;left:0;right:0;bottom:0;background:var(--card,#fff);border-radius:22px 22px 0 0;padding:1rem 1rem calc(1rem + env(safe-area-inset-bottom,0px));box-shadow:0 -12px 40px rgba(0,0,0,.25);display:none;flex-direction:column;gap:.6rem}
#lvCampus .lvc-custom.on{display:flex}
#lvCampus .lvc-custom input{width:100%;box-sizing:border-box;font-size:16px;border-radius:12px;padding:.8rem 1rem;border:1.5px solid var(--border,#dde5e0);background:var(--bg,#f4f7f5);color:inherit}
.lv-campus-field{margin:.2rem 0 .5rem}
.lv-campus-btn{display:flex;align-items:center;gap:.7rem;width:100%;border:1.5px solid var(--border,#dde5e0);background:var(--input-bg,var(--card,#fff));color:inherit;border-radius:14px;padding:.55rem .8rem;font:inherit;cursor:pointer;text-align:left}
.lv-campus-btn .ico{width:2.1rem;height:2.1rem;border-radius:50%;background:#fff;display:grid;place-items:center;overflow:hidden;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.07)}
.lv-campus-btn .ico img{width:100%;height:100%;object-fit:contain;padding:3px;box-sizing:border-box}
.lv-campus-btn .ico i{color:var(--primary,#16a34a)}
.lv-campus-btn .t{flex:1;min-width:0;font-weight:700;font-size:.92rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.lv-campus-btn .t small{display:block;font-weight:600;color:var(--text-muted,#667);font-size:.7rem}
#lvCampusBar{margin:.2rem 0 1rem;background:var(--card,#fff);border:1px solid var(--border,#dde5e0);border-radius:16px;padding:.35rem;box-shadow:0 1px 2px rgba(15,29,23,.05)}
#lvCampusBar .lvcb-main{display:flex;align-items:center;gap:.7rem;width:100%;padding:.45rem .5rem;border:0;background:transparent;color:inherit;font:inherit;cursor:pointer;text-align:left;border-radius:12px;-webkit-tap-highlight-color:transparent}
#lvCampusBar .lvcb-main:active{background:color-mix(in srgb,var(--text,#000) 5%,transparent)}
#lvCampusBar .ico{width:2.5rem;height:2.5rem;border-radius:50%;background:#fff;display:grid;place-items:center;overflow:hidden;flex:none;border:1px solid var(--border,#dde5e0);color:var(--primary,#16a34a)}
#lvCampusBar .ico img{width:100%;height:100%;object-fit:contain;padding:5px;box-sizing:border-box}
#lvCampusBar .t{flex:1;min-width:0;display:flex;flex-direction:column;gap:.1rem}
#lvCampusBar .t small{font-size:.66rem;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--text-muted,#667)}
#lvCampusBar .t b{font-size:1rem;font-weight:700;line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#lvCampusBar .chev{color:var(--text-muted,#667);display:grid;place-items:center;flex:none}
#lvCampusBar .seg{display:grid;grid-template-columns:1fr 1fr;gap:3px;margin:.3rem .15rem .15rem;padding:3px;border-radius:12px;background:color-mix(in srgb,var(--text,#000) 6%,transparent)}
#lvCampusBar .seg button{border:0;background:transparent;color:var(--text-muted,#667);font:inherit;font-size:.8rem;font-weight:600;padding:.5rem .4rem;border-radius:9px;cursor:pointer;transition:background .15s,color .15s}
#lvCampusBar .seg button.on{background:var(--card,#fff);color:var(--text,#0f1d17);box-shadow:0 1px 3px rgba(15,29,23,.14)}

.lvc-dup{position:absolute;inset:0;z-index:5;display:flex;align-items:flex-end;pointer-events:none}
.lvc-dup.on{pointer-events:auto}
.lvc-dup-back{position:absolute;inset:0;background:rgba(0,0,0,0);transition:background .2s}
.lvc-dup.on .lvc-dup-back{background:rgba(0,0,0,.45)}
.lvc-dup-sheet{position:relative;width:100%;max-height:82%;overflow:auto;background:var(--card,#fff);color:var(--text,#111);border-radius:24px 24px 0 0;padding:.6rem 1.1rem calc(1.1rem + env(safe-area-inset-bottom,0px));transform:translateY(100%);transition:transform .24s cubic-bezier(.2,.8,.2,1);box-shadow:0 -12px 40px rgba(0,0,0,.3)}
.lvc-dup.on .lvc-dup-sheet{transform:none}
.lvc-dup-grab{width:42px;height:4px;border-radius:4px;background:color-mix(in srgb,var(--text,#000) 18%,transparent);margin:0 auto .8rem}
.lvc-dup-sheet h3{margin:0 0 .25rem;font-size:1.2rem}
.lvc-dup-sheet p{margin:0 0 .8rem;color:var(--text-muted,#667);font-size:.9rem}
.lvc-dup-list{display:flex;flex-direction:column;gap:.45rem;margin-bottom:.9rem}
.lvc-dup-row{display:flex;align-items:center;gap:.75rem;width:100%;text-align:left;padding:.65rem .75rem;border-radius:16px;border:1.5px solid var(--border,#dde5e0);background:var(--bg,#f6f8f7);color:inherit;cursor:pointer}
.lvc-dup-row .lvc-logo{width:2.6rem;height:2.6rem;border-radius:12px;display:grid;place-items:center;overflow:hidden;flex:0 0 auto;background:var(--card,#fff);color:var(--primary,#16a34a)}
.lvc-dup-row .lvc-logo img{width:100%;height:100%;object-fit:contain}
.lvc-dup-row .t{flex:1;min-width:0;display:flex;flex-direction:column}
.lvc-dup-row .t b{font-size:.95rem;line-height:1.25}
.lvc-dup-row .t small{color:var(--text-muted,#667);font-size:.74rem}
.lvc-dup-new{width:100%;padding:.85rem;border-radius:14px;border:1.5px dashed color-mix(in srgb,var(--primary,#16a34a) 55%,transparent);background:transparent;color:var(--primary,#16a34a);font-weight:700;cursor:pointer}
.lvc-dup-note{display:block;text-align:center;margin-top:.6rem;color:var(--text-muted,#667)}
/* ---- request-photos-style ---- */
.req-photos{display:flex;flex-wrap:wrap;gap:.55rem;margin:.2rem 0 .6rem}
.req-ph{position:relative;width:4.6rem;height:4.6rem;border-radius:14px;overflow:hidden;border:1px solid var(--border);background:var(--card)}
.req-ph img{width:100%;height:100%;object-fit:cover;display:block}
.req-ph>button{position:absolute;top:3px;right:3px;width:1.4rem;height:1.4rem;border-radius:50%;border:0;background:rgba(0,0,0,.6);color:#fff;font-size:.65rem;cursor:pointer}
.req-ph.add{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.2rem;border:1.5px dashed color-mix(in srgb,var(--primary) 55%,var(--border));background:color-mix(in srgb,var(--primary) 6%,transparent);color:var(--primary);font:inherit;font-size:.68rem;font-weight:700;cursor:pointer;padding:0}
.req-ph.add i{font-size:1.1rem}
.req-ph-row{display:flex;gap:.45rem;flex-wrap:wrap;margin:.5rem 0}
.req-ph-thumb{width:4.2rem;height:4.2rem;border-radius:12px;overflow:hidden;border:1px solid var(--border);padding:0;background:var(--card);cursor:zoom-in}
.req-ph-thumb img{width:100%;height:100%;object-fit:cover;display:block}
.req-lightbox{position:fixed;inset:0;z-index:2147483500;background:rgba(0,0,0,.92);display:flex;flex-direction:column;align-items:center;justify-content:center}
.req-lightbox .x{position:absolute;top:calc(.8rem + env(safe-area-inset-top,0px));right:.9rem;width:2.5rem;height:2.5rem;border-radius:50%;border:0;background:rgba(255,255,255,.15);color:#fff;font-size:1.1rem;cursor:pointer;z-index:2}
.req-lightbox .strip{display:flex;width:100%;overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.req-lightbox .strip::-webkit-scrollbar{display:none}
.req-lightbox .strip img{flex:0 0 100%;width:100%;max-height:82vh;object-fit:contain;scroll-snap-align:center}
.req-lightbox .n{color:#fff;font-weight:700;margin-top:.8rem;font-size:.85rem;opacity:.8}
.vr-pref{display:flex;flex-direction:column;gap:.45rem;margin:0 0 .9rem;padding:.7rem .8rem;border-radius:14px;border:1px solid var(--border);background:color-mix(in srgb,var(--text) 3%,var(--card))}
.vr-pref-label{font-weight:800;font-size:.84rem}
.vr-pref-label i{color:var(--primary);margin-right:.35rem}
.vr-pref-seg{display:flex;background:color-mix(in srgb,var(--text) 7%,transparent);border-radius:999px;padding:3px;align-self:flex-start}
.vr-pref-seg button{border:0;background:transparent;color:inherit;font:inherit;font-size:.78rem;font-weight:800;padding:.4rem .95rem;border-radius:999px;cursor:pointer}
.vr-pref-seg button.on{background:var(--primary);color:#fff}
.vr-pref small{font-size:.74rem;line-height:1.35}
/* ---- lv-campus2-style ---- */
.lvv{margin:.2rem 0 .8rem;padding:.2rem 0}
.lvv .lvv-hint{font-size:.74rem;color:var(--text-muted,#667);margin:.35rem 0 .7rem;line-height:1.4}
.lvv-seg{display:grid;grid-template-columns:repeat(3,1fr);gap:3px;padding:3px;border-radius:12px;background:color-mix(in srgb,var(--text,#000) 6%,transparent);margin:.25rem 0 .5rem}
.lvv-seg button{border:0;background:transparent;color:var(--text-muted,#667);font:inherit;font-size:.76rem;font-weight:700;padding:.55rem .25rem;border-radius:9px;cursor:pointer;line-height:1.2}
.lvv-seg button.on{background:var(--card,#fff);color:var(--text,#0f1d17);box-shadow:0 1px 3px rgba(15,29,23,.14)}
.lvv-chips{display:flex;flex-wrap:wrap;gap:.35rem;margin:.45rem 0 0}
.lvv-chips span{font-size:.72rem;font-weight:700;padding:.28rem .6rem;border-radius:999px;border:1px solid var(--border,#dde5e0);background:var(--card,#fff)}
.lv-sv{margin:.9rem 0;padding:1rem;border-radius:16px;border:1px solid var(--border,#dde5e0);background:var(--card,#fff)}
.lv-sv h4{margin:0 0 .15rem;font-size:1rem;font-weight:800}
.lv-sv .sub{font-size:.76rem;color:var(--text-muted,#667);margin:0 0 .7rem;line-height:1.4}
.lv-sv .st{display:inline-flex;align-items:center;gap:.4rem;font-size:.74rem;font-weight:800;padding:.3rem .65rem;border-radius:999px;margin-bottom:.6rem}
.lv-sv .st.pending{background:#fef3c7;color:#92400e}.lv-sv .st.approved{background:#dcfce7;color:#166534}.lv-sv .st.rejected{background:#fee2e2;color:#991b1b}
.lv-sv .up{display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin:.4rem 0 .6rem}
