:root:root:root body #app .storefront-cover-edit i,:root:root:root body #app .ep-cam i,:root:root:root body #app .avatar-edit-badge i{color:var(--text,#111)!important;-webkit-text-fill-color:currentColor!important;font-size:.95rem!important;margin:0!important}
:root:root:root body #app .ep-cam{right:0!important;bottom:0!important}
/* on your own storefront the banner pencil sits top-left so it no longer stacks under the three dots */
