/* the profile page's banner is as tall as on the storefront */
:root:root:root body #app .ep-banner .storefront-cover{height:176px!important}

/* ===== follow / following buttons: one glossy green family everywhere (search, vendors, followers) ===== */
html body #app .vendor-card-follow-btn,html body #app .fn-follow,html body #app .vd-follow,html body #app .sr-follow{flex:0 0 auto;min-width:6.4rem;white-space:nowrap!important;min-height:2.5rem;padding:0 1rem!important;border-radius:12px!important;border:0!important;font-weight:800!important;font-size:.9rem!important;display:inline-flex!important;align-items:center;justify-content:center;gap:.35rem;background:linear-gradient(135deg,#22c55e,#0d9f6e)!important;color:#fff!important;box-shadow:0 4px 12px rgba(13,159,110,.32),inset 0 1px 0 rgba(255,255,255,.28)!important}
html body #app .vendor-card-follow-btn.following,html body #app .fn-follow.following,html body #app .vd-follow.following,html body #app .sr-follow.following{background:linear-gradient(135deg,#e8fbf0,#c7f0d9)!important;color:#0b7a49!important;box-shadow:0 3px 10px rgba(13,159,110,.18),inset 0 1px 0 rgba(255,255,255,.7)!important;border:1px solid #8fdcb4!important}
:root[data-theme="dark"] body #app .vendor-card-follow-btn.following,:root[data-theme="black"] body #app .vendor-card-follow-btn.following,:root[data-theme="dark"] body #app .fn-follow.following,:root[data-theme="black"] body #app .fn-follow.following,:root[data-theme="dark"] body #app .vd-follow.following,:root[data-theme="black"] body #app .vd-follow.following{background:linear-gradient(135deg,#123826,#0f2c1e)!important;color:#6ee7a8!important;border-color:#1f6a45!important;box-shadow:0 3px 10px rgba(34,197,94,.15)!important}
/* the campus chip never takes a grid cell on a vendor card (it used to push the button over the name) */
html body #app .vd-card{position:relative}
html body #app .vd-card > .lv-camp-line{position:absolute!important;top:.55rem;right:.6rem;margin:0!important;max-width:7rem;z-index:2}
html body #app .vendors-list-mode .vd-card .vd-follow,html body #app .vendors-list-mode .vendor-card-follow-btn{grid-column:3}
html body #app .sr-vendor-row .sr-main{min-width:0;flex:1 1 0}
html body #app .sr-vendor-row .sr-side{flex:0 0 auto;margin-left:.4rem}

/* Browse everything: a search icon inside the search bar, with the text clear of it */
