.ap-who{display:inline-flex;align-items:center;gap:.6rem;min-width:0}
.ap-av{position:relative;width:2.3rem;height:2.3rem;flex:0 0 2.3rem;border-radius:50%;overflow:hidden;background:color-mix(in srgb,var(--primary,#3fb97f) 18%,var(--card,#fff));display:grid;place-items:center;color:var(--primary,#16a34a);font-size:.78rem}
