/* ---- occasional welcome pop-up (lv-promo) ---- */
.lv-promo{position:fixed;inset:0;z-index:100050;display:flex;align-items:center;justify-content:center;padding:24px 18px calc(24px + env(safe-area-inset-bottom));background:rgba(8,12,24,.62);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);animation:lvPromoFade .25s ease both;--p1:#0b7a52;--p2:#19c486;--p3:#d9fbe9;--hl:#ffe14d}
.lv-promo-purple{--p1:#4c1d95;--p2:#8b5cf6;--p3:#efe7ff;--hl:#ffe14d}
.lv-promo-blue{--p1:#0c3b66;--p2:#2b8ce0;--p3:#e2f0ff;--hl:#ffe14d}
.lv-promo-amber{--p1:#064e3b;--p2:#10b981;--p3:#fff4d6;--hl:#ffd23f}
.lv-promo-out{animation:lvPromoFadeOut .22s ease both}
.lv-promo-wrap{width:100%;max-width:340px;display:flex;flex-direction:column;align-items:center;gap:22px;animation:lvPromoPop .5s cubic-bezier(.2,1.35,.4,1) both}
.lv-promo-out .lv-promo-wrap{animation:lvPromoDrop .22s ease both}
.lv-promo-card{position:relative;width:100%;margin-top:118px;padding:96px 22px 24px;border-radius:30px;color:#fff;text-align:center;background:radial-gradient(120% 70% at 50% 0%,var(--p2) 0%,var(--p1) 70%);box-shadow:0 30px 60px -18px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.25);overflow:visible;isolation:isolate}
.lv-promo-card::before{content:"";position:absolute;inset:0;border-radius:inherit;z-index:-1;background:radial-gradient(circle at 12% 88%,rgba(255,255,255,.14) 0 22%,transparent 23%),radial-gradient(circle at 92% 70%,rgba(255,255,255,.10) 0 14%,transparent 15%),repeating-linear-gradient(135deg,rgba(255,255,255,.05) 0 2px,transparent 2px 14px)}
.lv-promo-glow{position:absolute;left:50%;top:-30px;width:240px;height:240px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.55),rgba(255,255,255,0) 65%);pointer-events:none;z-index:-1}
.lv-promo-art{position:absolute;left:50%;top:-150px;width:250px;height:240px;object-fit:contain;transform:translateX(-50%);filter:drop-shadow(0 18px 22px rgba(0,0,0,.35));animation:lvPromoFloat 4s ease-in-out .6s infinite;pointer-events:none}
.lv-promo-body{position:relative;display:flex;flex-direction:column;align-items:center;gap:10px}
.lv-promo-kicker{display:inline-flex;align-items:center;gap:7px;padding:6px 12px;border-radius:999px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.28);font-size:.74rem;font-weight:700;letter-spacing:.02em}
.lv-promo-kicker i{color:var(--hl)}
html:root:root .lv-promo .lv-promo-title{margin:2px 0 0;display:flex;flex-direction:column;font-size:2.35rem;line-height:1;font-weight:900;letter-spacing:-.03em;text-transform:uppercase;color:#fff;text-shadow:0 3px 0 rgba(0,0,0,.18)}
.lv-promo-hl{color:var(--hl)}
html:root:root .lv-promo .lv-promo-sub{margin:4px 4px 6px;font-size:.92rem;line-height:1.45;color:rgba(255,255,255,.9);font-weight:500}
html:root:root .lv-promo .lv-promo-cta{display:inline-flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:54px;margin-top:4px;border:0;border-radius:999px;background:var(--hl);color:#1a1a1a;font-size:1.06rem;font-weight:800;box-shadow:0 6px 0 rgba(0,0,0,.22),0 14px 24px -10px rgba(0,0,0,.5);cursor:pointer;transition:transform .12s ease,box-shadow .12s ease}
html:root:root .lv-promo .lv-promo-cta:active{transform:translateY(4px);box-shadow:0 2px 0 rgba(0,0,0,.22)}
html:root:root .lv-promo .lv-promo-cta i{font-size:.9rem}
html:root:root .lv-promo .lv-promo-cta:focus-visible,html:root:root .lv-promo .lv-promo-x:focus-visible{outline:3px solid #fff;outline-offset:3px}
html:root:root .lv-promo .lv-promo-x{width:48px;height:48px;display:grid;place-items:center;padding:0;border-radius:50%;border:2px solid rgba(255,255,255,.9);background:rgba(255,255,255,.08);color:#fff;font-size:1.2rem;cursor:pointer}
.lv-promo-coin{position:absolute;display:grid;place-items:center;width:44px;height:44px;border-radius:50%;font-weight:900;font-size:1.15rem;color:#8a5a00;background:radial-gradient(circle at 35% 30%,#fff3b0,#ffcf3a 45%,#e9a300 100%);box-shadow:inset 0 -3px 0 rgba(0,0,0,.15),0 8px 16px -6px rgba(0,0,0,.45);animation:lvPromoBob 3.2s ease-in-out infinite;z-index:2}
.lv-promo-coin.c1{left:-8px;top:-34px;transform:rotate(-18deg)}
.lv-promo-coin.c2{right:-6px;top:30px;width:36px;height:36px;font-size:.95rem;animation-delay:-1.4s}
.lv-promo-spark{position:absolute;width:10px;height:10px;background:#fff;clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);opacity:.85;animation:lvPromoTwinkle 2.4s ease-in-out infinite}
.lv-promo-spark.s1{left:26px;top:58px}.lv-promo-spark.s2{right:30px;top:-46px;width:14px;height:14px;animation-delay:-.8s}.lv-promo-spark.s3{left:46%;bottom:18px;width:8px;height:8px;animation-delay:-1.6s;opacity:.5}
@keyframes lvPromoFade{from{opacity:0}to{opacity:1}}
@keyframes lvPromoFadeOut{to{opacity:0}}
@keyframes lvPromoPop{from{opacity:0;transform:translateY(40px) scale(.86)}to{opacity:1;transform:none}}
@keyframes lvPromoDrop{to{opacity:0;transform:translateY(24px) scale(.94)}}
@keyframes lvPromoFloat{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(-8px)}}
@keyframes lvPromoBob{0%,100%{translate:0 0}50%{translate:0 -7px}}
@keyframes lvPromoTwinkle{0%,100%{transform:scale(.6);opacity:.3}50%{transform:scale(1);opacity:.95}}
@media (max-height:640px){.lv-promo-card{margin-top:92px;padding-top:80px}.lv-promo-art{top:-120px;width:200px;height:190px}html:root:root .lv-promo .lv-promo-title{font-size:2rem}}
@media (prefers-reduced-motion:reduce){.lv-promo,.lv-promo-wrap,.lv-promo-art,.lv-promo-coin,.lv-promo-spark{animation:none!important}}
.lv-promo-wrap:focus{outline:none}

