.adp-pill{flex:none;padding:4px 10px;border-radius:999px;background:#fff1e6;color:#c2410c;font-size:.7rem;font-weight:800;text-transform:capitalize;white-space:nowrap}
.adp-st-completed{background:#e6f8ef;color:#047857}.adp-st-cancelled{background:#fdecec;color:#b91c1c}.adp-st-disputed{background:#fff1e6;color:#c2410c}
