.od-bell-tip::before{content:"";position:absolute;top:-5px;right:14px;width:10px;height:10px;background:#111;transform:rotate(45deg);border-radius:2px}
@keyframes lvBellRing{0%,60%,100%{transform:rotate(0)}66%{transform:rotate(16deg)}72%{transform:rotate(-14deg)}78%{transform:rotate(10deg)}84%{transform:rotate(-8deg)}90%{transform:rotate(0)}}
