/* Levi's button shows a chart icon while the analysis page is open */
body.lv-analysis-open #aiChatFab>*:not(.lv-fab-chart){opacity:0!important}
.lv-fab-chart{position:absolute!important;inset:10%;width:80%!important;height:80%!important;object-fit:contain;z-index:5;pointer-events:none;opacity:1!important}
body.lv-analysis-open #aiChatFab{z-index:2147483001!important}

/* ===== Transfer page: the recipient field, its suggestions, and Recents / Favourites =====
   Anything given the `hidden` attribute inside the wallet pages really is hidden (a few of these elements set their own
   display, which used to win over `hidden`: an empty green bar showed above the @tag field and both lists showed at once). */
.lvw-sheet-wrap [hidden],.lvw-page [hidden],.lv-mvp [hidden]{display:none!important}
/* one person: picture, then name over @tag (each on its own line, cut with … when long) */
.lw-pp-av{flex:none;width:44px;height:44px;border-radius:50%;overflow:hidden;display:grid;place-items:center;background:#e3f6ee;color:#0b7d52;font-weight:800;font-size:1.05rem;line-height:1}
.lw-pp-av img{width:100%;height:100%;object-fit:cover;display:block}
.lw-pp-txt{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:left}
.lw-pp-txt b{display:block;font-size:.95rem;font-weight:700;line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lw-pp-txt small{display:block;font-size:.8rem;font-weight:500;line-height:1.3;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the chosen recipient, in place of the field */
.lw-locked{display:flex;align-items:center;gap:12px;padding:10px 6px 10px 12px;border-radius:16px;background:rgba(16,163,109,.08)}
.lw-locked .lw-pp-txt b i{color:#10a36d;font-size:.78rem;margin-left:3px}
.lw-locked button{flex:none;border:0;background:none;color:#0d8a43;font:inherit;font-size:.9rem;font-weight:700;padding:0 10px;min-height:44px;cursor:pointer}
/* suggestions under the field */
.lw-sugg{display:flex;flex-direction:column;gap:0;margin-top:6px}
.lw-sugg:empty{display:none}
.lw-sugg-cap{margin:4px 8px 0;font-size:.72rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#6b7280}
/* a tappable person row (suggestions, Recents, Favourites, Beneficiaries) */
.lw-person,.lw-pp-row{display:flex;align-items:center;gap:12px;width:100%;min-height:60px;margin:0;padding:8px;border:0;border-radius:14px;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer;-webkit-tap-highlight-color:transparent}
.lw-person>i,.lw-pp-row>i{flex:none;width:16px;text-align:center;font-size:.72rem;color:#9ca3af}
.lw-person:active,.lw-pp-row:active{background:rgba(16,163,109,.09)}
@media (hover:hover){.lw-person:hover,.lw-pp-row:hover{background:rgba(16,163,109,.06)}}
/* Recents / Favourites: on the page itself (no extra card), a two-way switch and a search button */
.lw-pp{margin:8px 0 0;padding:0 4px}
.lw-pp-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:4px 4px 8px}
.lw-pp-tabs{display:inline-flex;padding:3px;border-radius:999px;background:rgba(120,120,128,.12)}
.lw-pp-tabs button{border:0;margin:0;background:none;color:#6b7280;font:inherit;font-size:.88rem;font-weight:700;padding:0 16px;min-height:36px;border-radius:999px;cursor:pointer}
.lw-pp-tabs button.on{background:#fff;color:#0d8a43;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.lw-pp-all{flex:none;width:44px;height:44px;border:0;border-radius:50%;background:none;color:#374151;display:grid;place-items:center;font-size:1rem;cursor:pointer}
.lw-pp-all:active{background:rgba(120,120,128,.14)}
.lw-pp-list,.lw-pp-all-list{display:flex;flex-direction:column}
.lw-pp-all-list{margin-top:8px}
/* nobody here yet */
.lw-pp-empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:20px 16px 12px}
.lw-pp-empty-ic{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:rgba(16,163,109,.1);color:#10a36d;margin-bottom:6px}
.lw-pp-empty b{font-size:.95rem}
.lw-pp-empty small{font-size:.82rem;line-height:1.4;color:#6b7280;max-width:17rem}
:is([data-theme="dark"],[data-theme="black"]) .lw-pp-av{background:rgba(16,163,109,.2);color:#6ee7b7}
:is([data-theme="dark"],[data-theme="black"]) :is(.lw-pp-txt small,.lw-sugg-cap,.lw-pp-empty small,.lw-pp-tabs button){color:#9aa3b2}
:is([data-theme="dark"],[data-theme="black"]) .lw-pp-tabs{background:rgba(255,255,255,.08)}
:is([data-theme="dark"],[data-theme="black"]) .lw-pp-tabs button.on{background:#2b2b36;color:#4ade80;box-shadow:none}
:is([data-theme="dark"],[data-theme="black"]) .lw-pp-all{color:#e5e7eb}
:is([data-theme="dark"],[data-theme="black"]) .lw-locked{background:rgba(16,163,109,.14)}
:is([data-theme="dark"],[data-theme="black"]) .lw-locked button{color:#4ade80}

/* the Transfer page is one page: the whole of it has the page colour (not a white frame around a grey body) */
.lw-full .lvw-sheet{background:var(--bg,#f4f5f8)}
:root[data-theme="dark"] .lw-full .lvw-sheet,:root[data-theme="black"] .lw-full .lvw-sheet{background:#0b0b10}

/* Transaction history: the search button is a plain round icon, not a square box */
.lwh-filters{align-items:center}
html body .lwh-sbtn,:root[data-theme="dark"] .lwh-sbtn,:root[data-theme="black"] .lwh-sbtn{flex:none;width:44px;height:44px;padding:0;border:0;border-radius:50%;background:transparent;box-shadow:none;color:inherit;display:grid;place-items:center;font-size:1rem;cursor:pointer}
html body .lwh-sbtn:active{background:rgba(120,120,128,.14)}

/* ===== Levi with a subject (Analysis mode, a listing): a slim bar under his header ===== */
#aiChatPanel .lv-levi-mode{display:flex;align-items:center;gap:8px;margin:0 12px 8px;padding:4px 4px 4px 12px;border-radius:999px;background:rgba(16,163,109,.16);color:#0b7d52;font-size:.82rem;font-weight:700;line-height:1.2;flex:none}
#aiChatPanel .lv-levi-mode span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#aiChatPanel .lv-levi-mode button{flex:none;border:0;margin:0;background:rgba(255,255,255,.75);color:inherit;font:inherit;font-size:.78rem;font-weight:700;border-radius:999px;padding:0 12px;min-height:30px;cursor:pointer}
:is([data-theme="dark"],[data-theme="black"]) #aiChatPanel .lv-levi-mode{background:rgba(16,163,109,.2);color:#6ee7b7}
:is([data-theme="dark"],[data-theme="black"]) #aiChatPanel .lv-levi-mode button{background:rgba(255,255,255,.1)}
/* on the wallet's Analysis page, Levi's chat opens above the page (closing it goes back to the page) */
html:root:root:root body.lv-analysis-open #aiChatPanel{z-index:2147483002!important}
/* the listing pop-up's "Ask Levi about my listing": a full-width row above View / Close */
#vendorProductDetailsModal.vld-modal .modal-content>.flex .vld-levi{grid-column:1 / -1;background:#10a36d;color:#fff;border-color:#10a36d;gap:8px}

html body #app .orders-remind-all-btn{width:40px;height:40px;padding:0!important;border-radius:50%!important;display:inline-flex;align-items:center;justify-content:center;background:var(--card);border:1px solid var(--border);color:#d97706;cursor:pointer}
html body #app .orders-remind-all-btn:active{transform:scale(.94)}

html body #app .order-history-card{display:flex!important;align-items:center;gap:.7rem}
html body #app .order-history-thumb{width:54px;height:54px;border-radius:12px;object-fit:cover;flex:0 0 auto;background:var(--border)}
html body #app .order-history-main{flex:1 1 auto;min-width:0}

html body #app .ai-chat-msg-actions,html body .ai-chat-msg-actions{display:flex;gap:.9rem;margin-top:.45rem}
html body .ai-chat-msg-act{background:none;border:0;padding:.15rem 0;font-size:.78rem;font-weight:600;color:var(--text-muted);cursor:pointer;display:inline-flex;align-items:center;gap:.3rem}
html body .ai-chat-msg-speak{display:none!important}
/* Levi send button: green with a white arrow in dark and black mode too (not a white circle) */
html[data-theme="dark"]:root:root body #aiChatPanel .ai-chat-input-row .icon-btn:last-child,html[data-theme="black"]:root:root body #aiChatPanel .ai-chat-input-row .icon-btn:last-child,html[data-theme="dark"]:root:root body #aiChatPanel button[onclick*="sendAiChatMessage"],html[data-theme="black"]:root:root body #aiChatPanel button[onclick*="sendAiChatMessage"]{background:linear-gradient(135deg,#22c55e,#0b8a5f)!important;color:#fff!important;border:0!important;box-shadow:0 4px 12px rgba(11,138,95,.35)!important}
html[data-theme="dark"]:root:root body #aiChatPanel .ai-chat-input-row .icon-btn:last-child i,html[data-theme="black"]:root:root body #aiChatPanel .ai-chat-input-row .icon-btn:last-child i{color:#fff!important;-webkit-text-fill-color:#fff!important}
/* transaction history amounts sit flat on the page (the amount-box pill style leaked onto them) */
html body b.lw-amt,html:root body b.lw-amt,:root[data-theme="dark"] b.lw-amt,:root[data-theme="black"] b.lw-amt{display:inline!important;padding:0!important;border:0!important;background:none!important;box-shadow:none!important;border-radius:0!important;gap:0}
/* QR on dark and black mode: a soft framed panel that blends with the sheet. The squares stay dark on light so every phone can still scan it. */
:root[data-theme="dark"] .lvqr-code,:root[data-theme="black"] .lvqr-code{background:#eef3ef;padding:10px;box-shadow:0 0 0 3px rgba(34,197,94,.35),0 10px 30px rgba(0,0,0,.45)}
/* Cancel on the listing forms: readable in every mode */
:root:root:root:root:root:root:root body .lf-page .lm-actions .lf-cancel,:root:root:root:root:root:root:root body #productModal .lf-cancel,:root:root:root:root:root:root:root body #packageModal .lf-cancel{background:#fde2e2!important;background-image:none!important;color:#b91c1c!important;-webkit-text-fill-color:#b91c1c!important;border:1.5px solid #f2a9a9!important;font-weight:700!important}
:root[data-theme="dark"]:root:root:root:root:root:root body .lf-page .lm-actions .lf-cancel,:root[data-theme="black"]:root:root:root:root:root:root body .lf-page .lm-actions .lf-cancel,:root[data-theme="dark"]:root:root:root:root:root:root body #productModal .lf-cancel,:root[data-theme="black"]:root:root:root:root:root:root body #productModal .lf-cancel,:root[data-theme="dark"]:root:root:root:root:root:root body #packageModal .lf-cancel,:root[data-theme="black"]:root:root:root:root:root:root body #packageModal .lf-cancel{background:#dc2626!important;color:#fff!important;-webkit-text-fill-color:#fff!important;border-color:#dc2626!important}

.lv-hg{display:flex;align-items:center;gap:.8rem;margin-top:.7rem;padding:.6rem .8rem;border-radius:16px;background:var(--card);border:1px solid var(--border)}
.lv-hg .hg-stream{animation:lvHgFall .6s linear infinite}
@keyframes lvHgFall{to{stroke-dashoffset:-6}}
.lv-hg .hg-text{display:flex;flex-direction:column;gap:.1rem}
.lv-hg .hg-left{font-size:1.15rem;font-weight:800;font-variant-numeric:tabular-nums}
.lv-hg small{color:var(--text-muted);font-size:.78rem}
.od-status>.lv-hg{grid-column:1/-1;margin-top:.4rem}
/* Chat: sent bubble a touch deeper (like WhatsApp) so the ticks stand out; time then ticks at the far right */
:root{--chat-mine-bg:#1f7a55}
:root[data-theme="dark"],:root[data-theme="black"]{--chat-mine-bg:#14583e}
html body .chat-bubble.mine .chat-tick{color:rgba(255,255,255,.78)!important}
html body .chat-bubble.mine .chat-tick.read{color:#53bdeb!important;text-shadow:none!important}
html body .chat-bubble .chat-time{display:flex!important;justify-content:flex-end;align-items:center;gap:.3rem;width:100%}
html body .chat-bubble .chat-time-text{display:inline-flex;align-items:center;gap:.28rem}
html body .chat-bubble.mine .chat-tick{font-size:.82rem;margin-left:.1rem}
/* Typing: three bouncing dots in a small bubble at the bottom left, like WhatsApp (no text) */
html body .chat-typing-indicator{display:inline-flex;align-items:center;margin:.35rem 0 .2rem .6rem;padding:.6rem .85rem;border-radius:18px 18px 18px 6px;background:var(--card);border:1px solid var(--border);align-self:flex-start;width:max-content}
html body .chat-typing-indicator.hidden{display:none!important}
html body .chat-typing-indicator>span:last-child{display:none}
html body .chat-typing-dots{display:inline-flex;gap:.28rem;align-items:center}
html body .chat-typing-dots i{width:7px;height:7px;border-radius:50%;background:#8a9a93;display:block;animation:lvTypingBounce 1s infinite ease-in-out}
html body .chat-typing-dots i:nth-child(2){animation-delay:.15s}
html body .chat-typing-dots i:nth-child(3){animation-delay:.3s}
@keyframes lvTypingBounce{0%,60%,100%{transform:translateY(0);opacity:.55}30%{transform:translateY(-5px);opacity:1}}
/* No conversations yet: no Messages icon in the header, the search bar fills the space */
html.lv-no-convos #messagesWrap,html.lv-no-convos button.icon-btn[onclick="navigate('messages')"]{display:none!important}
/* Product page, Temu-style: the photo is the first thing you see, edge to edge at the top; the name, price and the rest follow */
:root:root:root:root:root body #app .product-detail-card{display:flex!important;flex-direction:column;padding-top:0!important;overflow:hidden}
:root:root:root:root:root body #app .product-detail-card .product-detail-media{order:-3;margin:0 -1rem .6rem!important;width:calc(100% + 2rem)!important;max-width:none!important;border-radius:0!important;background:var(--card)}
:root:root:root:root:root body #app .product-detail-card .product-detail-top-actions{order:-4;position:absolute!important;top:.7rem;right:.7rem;z-index:5;display:flex;gap:.45rem}
:root:root:root:root:root body #app .product-detail-card .product-detail-top-actions button{background:rgba(255,255,255,.92)!important;color:#111!important;backdrop-filter:blur(4px);box-shadow:0 2px 8px rgba(0,0,0,.18)}
:root:root:root:root:root body #app .product-detail-card .product-gallery-main,:root:root:root:root:root body #app .product-detail-card .product-gallery-slide img{border-radius:0!important}
:root:root:root:root:root body #app .product-detail-card .product-detail-title{order:-2;margin:.2rem 0 .5rem}
:root:root:root:root:root body #app .product-detail-card>*{order:0}
:root:root:root:root:root body #app .product-detail-card .product-price-hero{order:-1!important;margin:.1rem 0 .6rem}

.lv-hg{padding:.45rem .7rem!important;gap:.65rem!important;border-radius:14px!important}
.lv-hg svg{flex:0 0 auto;filter:drop-shadow(0 2px 3px rgba(60,40,10,.28))}
.lv-hg .hg-left{font-size:1rem!important}
.lv-hg small{font-size:.74rem!important;line-height:1.25}
/* Product page, edge to edge like Temu: the photo fills the top and both sides; a thin line under it; then the name, price, vendor and the rest, compact */
@media(max-width:899px){
:root:root:root:root:root:root body #app .product-detail-card{width:100vw!important;max-width:100vw!important;margin-left:calc(50% - 50vw)!important;margin-right:calc(50% - 50vw)!important;border-radius:0!important;border-left:0!important;border-right:0!important;border-top:0!important;box-shadow:none!important;padding-left:1rem!important;padding-right:1rem!important}
:root:root:root:root:root:root body #app .product-detail-card .product-detail-media{margin:0 -1rem .7rem!important;width:calc(100% + 2rem)!important;border-radius:0!important;border-bottom:1px solid var(--border)}
:root:root:root:root:root:root body #app .product-detail-card .product-gallery-main,:root:root:root:root:root:root body #app .product-detail-card .product-gallery-carousel,:root:root:root:root:root:root body #app .product-detail-card .product-gallery-track,:root:root:root:root:root:root body #app .product-detail-card .product-gallery-slide,:root:root:root:root:root:root body #app .product-detail-card .product-gallery-slide img{border-radius:0!important}
:root:root:root:root:root:root body #app .product-detail-card .product-gallery-slide img{width:100%;aspect-ratio:1/1;object-fit:cover}
:root:root:root:root:root:root body #app .product-detail-card .product-detail-top-actions{top:.8rem;right:.9rem}
:root:root:root:root:root:root body #app .product-detail-card .product-detail-title{font-size:1.15rem!important;line-height:1.3;padding-right:0!important;margin:.1rem 0 .3rem}
}

/* product page: vendor rating sits on the price row (compact, like Temu) */
:root:root:root:root:root:root body #app .product-detail-card .product-price-hero{position:relative;padding-right:5.5rem!important;margin:0 0 .3rem!important}
:root:root:root:root:root:root body #app .product-detail-card .product-price-hero .pph-rating{position:absolute;right:.1rem;top:50%;transform:translateY(-50%);margin:0;white-space:nowrap}
:root:root:root:root:root:root body #app .product-detail-card:has(.pph-rating) .product-detail-actions{display:none!important}
:root:root:root:root:root:root body #app .product-detail-card .product-detail-title{margin-bottom:.15rem!important;min-height:0!important}

/* Chat: the sent bubble is ONE flat green (no gradient, no glow) so the ticks read clearly, like WhatsApp */
:root:root:root:root{--chat-mine-bg:#1a6b4a;--chat-mine-text:#fff}
:root[data-theme="dark"]:root:root:root,:root[data-theme="black"]:root:root:root{--chat-mine-bg:#0f4f3a}
:root:root:root:root body .chat-bubble.mine,:root:root:root:root body .chat-page-wrap .chat-bubble.mine{background:var(--chat-mine-bg)!important;background-image:none!important;box-shadow:none!important;filter:none!important;backdrop-filter:none!important;border:0!important}
:root:root:root:root body .chat-bubble.mine::before,:root:root:root:root body .chat-bubble.mine::after{background:none!important;box-shadow:none!important}
:root:root:root:root body .chat-bubble.mine.lv-stk-only,:root:root:root:root body .chat-bubble.theirs.lv-stk-only{background:transparent!important;box-shadow:none!important}
.chat-bubble-text img.lv-stk{width:6.5rem;height:6.5rem;object-fit:contain;display:block}
/* sticker / emoji panels in messages and Levi */
.lv-msgstk{display:grid;grid-template-columns:repeat(6,1fr);gap:.25rem;padding:.5rem;margin:.3rem .5rem;border:1px solid var(--border,rgba(128,128,128,.3));border-radius:16px;background:var(--card,#111);max-height:12rem;overflow:auto}
.lv-msgstk[hidden]{display:none}
.lv-msgstk button{border:0;background:transparent;padding:.2rem;border-radius:10px;cursor:pointer;display:grid;place-items:center;font-size:1.6rem}
.lv-msgstk button:active{background:color-mix(in srgb,var(--text,#111) 10%,transparent)}
.lv-msgstk img{width:2.8rem;height:2.8rem;object-fit:contain}
.chat-input-row>.lv-stk-tog{align-self:center}
/* wallet icons in the "How do you want to pay?" sheet: white on the green and blue tiles in every mode */
:root:root:root body .lw-pay-ic i,:root[data-theme] body .lw-pay-ic i{color:#fff!important;-webkit-text-fill-color:#fff!important}

/* ===== Product page, flat like Temu: no cards, thin lines between sections, no gap above the photo ===== */
:root:root:root:root:root:root:root body #app .product-detail-card{display:flex!important;flex-direction:column!important;background:transparent!important;background-image:none!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;margin-top:0!important;gap:0!important}
:root:root:root:root:root:root:root body #app .product-detail-card>*{order:30}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-detail-top-actions{order:-9}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-detail-media{order:1!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-gallery-varieties{order:2!important}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-gallery-variant-meta{order:3!important}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-detail-title{order:4!important;padding:.7rem .9rem 0!important;margin:0!important}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-price-hero{order:5!important;padding:.4rem .9rem .7rem!important;margin:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-detail-actions{display:none!important}
/* the info block dissolves into the page so its rows can be placed one by one */
:root:root:root:root:root:root:root body #app .product-detail-card>.product-detail-info{display:contents!important}
:root:root:root:root:root:root:root body #app .product-detail-card .product-detail-info>.pd-about{order:6!important;margin:0!important;padding:.1rem .9rem!important;border:0!important;border-top:1px solid var(--border,rgba(128,128,128,.25))!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}
:root:root:root:root:root:root:root body #app .product-detail-card .product-detail-info>p:first-child{order:7!important;margin:0!important;padding:.75rem .9rem!important;border-top:1px solid var(--border,rgba(128,128,128,.25))!important;border-bottom:1px solid var(--border,rgba(128,128,128,.25))!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}
:root:root:root:root:root:root:root body #app .product-detail-card .product-detail-info>.pd-condition{order:8!important;margin:0!important;padding:.6rem .9rem!important;border-bottom:1px solid var(--border,rgba(128,128,128,.25))!important}
:root:root:root:root:root:root:root body #app .product-detail-card .product-detail-vendor-link{background:transparent!important;box-shadow:none!important;border:0!important;padding:0!important}
:root:root:root:root:root:root:root body #app .product-detail-card>.product-detail-stats{order:9!important;padding:.6rem .9rem!important;border-bottom:1px solid var(--border,rgba(128,128,128,.25))!important;background:transparent!important;box-shadow:none!important;border-radius:0!important}
:root:root:root:root:root:root:root body #app .product-detail-card .product-comments-panel,:root:root:root:root:root:root:root body #app .product-detail-card .product-reviews-body{background:transparent!important;box-shadow:none!important;border-radius:0!important}
