html[data-theme="black"]:root:root body #lvqrSheet .lvqr-card{background:#101315!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-card :is(h3,.lvqr-by,.lvqr-by span,.lvqr-hint,.lvqr-brand),html[data-theme="black"]:root:root body #lvqrSheet .lvqr-card :is(h3,.lvqr-by,.lvqr-by span,.lvqr-hint,.lvqr-brand){color:#e8edf2!important;-webkit-text-fill-color:#e8edf2!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-card .lvqr-body,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-card .lvqr-body{background:transparent!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code{background:#e9eeea!important}

/* suggestion reply: small pen / trash icons at the far right */
.sg-reply-acts{display:flex;justify-content:flex-end;gap:.4rem;margin-top:.35rem}
.sg-ico-btn{width:2rem;height:2rem;border-radius:50%;border:0;background:color-mix(in srgb,var(--text,#111) 8%,transparent);color:var(--text-muted,#6b7280);display:inline-grid;place-items:center;cursor:pointer}
.sg-ico-btn:last-child{color:#e11d48}

/* chat pictures keep their size while loading (no small grey box that then grows) */
.chat-bubble .chat-image-attachment{display:block;width:min(15rem,62vw);aspect-ratio:4/3;background:color-mix(in srgb,var(--text,#111) 8%,transparent);border-radius:14px;overflow:hidden;padding:0;border:0}
.chat-bubble .chat-image-attachment img.msg-attachment-img{width:100%;height:100%;object-fit:cover;display:block}

/* "No photo yet": a soft colour per listing (like the banners), with a clean picture icon */
.lv-noimg{--ni-h:160;background:linear-gradient(135deg,hsl(var(--ni-h) 72% 90%),hsl(calc(var(--ni-h) + 40) 70% 80%))!important;color:hsl(var(--ni-h) 42% 34%)!important;font-size:.72rem;font-weight:800}
.lv-noimg svg{opacity:1!important}
html[data-theme="dark"] .lv-noimg,html[data-theme="black"] .lv-noimg{background:linear-gradient(135deg,hsl(var(--ni-h) 38% 22%),hsl(calc(var(--ni-h) + 40) 38% 16%))!important;color:hsl(var(--ni-h) 65% 78%)!important}

/* product grids: no staggered (offset) right column, so there are no big gaps between cards */
html:root:root body #app #productGrid > .product-card-wrap:nth-child(even),html:root:root body #app .lm-related-grid > .product-card-wrap:nth-child(even){margin-top:0!important;margin-bottom:0!important}

/* "No photo yet": soft lilac / peach / rose / sky, icon only (no text) */
.lv-noimg{background:linear-gradient(135deg,hsl(var(--ni-h) 85% 93%),hsl(calc(var(--ni-h) + 14) 80% 87%))!important;color:hsl(var(--ni-h) 48% 52%)!important}
html[data-theme="dark"] .lv-noimg,html[data-theme="black"] .lv-noimg{background:linear-gradient(135deg,hsl(var(--ni-h) 30% 24%),hsl(calc(var(--ni-h) + 14) 30% 18%))!important;color:hsl(var(--ni-h) 70% 78%)!important}
/* shop page "Latest from" tiles: rounded, not pointy */
html body #app .storefront-product-mini>img,html body #app .storefront-product-mini>.mini-placeholder{border-radius:16px!important;overflow:hidden}
html body #app .storefront-product-mini>.mini-placeholder .lv-noimg{border-radius:16px}
/* product grid: the zig-zag is back, but gentler so the gaps stay small */
html:root:root body #app #productGrid > .product-card-wrap:nth-child(even),html:root:root body #app .lm-related-grid > .product-card-wrap:nth-child(even){margin-top:1.3rem!important;margin-bottom:-1.3rem!important}
/* share QR: in dark / black mode the code sits on a dark tile with light dots (the saved / shared picture stays normal) */
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code{background:#161b20!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code canvas,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code canvas{filter:invert(1) hue-rotate(180deg)}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code .lvqr-pic,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code .lvqr-pic{filter:none}
.lw-tag-change{align-self:flex-end}

/* suggestions page tabs */
.sg-tabs{display:flex;gap:.4rem;margin:.6rem 0 .8rem;padding:.25rem;border-radius:999px;background:color-mix(in srgb,var(--text,#111) 7%,transparent)}
.sg-tabs button{flex:1;border:0;background:transparent;color:var(--text-muted,#6b7280);font-weight:700;padding:.5rem .6rem;border-radius:999px;cursor:pointer}
.sg-tabs button.on{background:var(--card,#fff);color:var(--text,#111);box-shadow:0 1px 4px rgba(0,0,0,.12)}
[hidden].sg-list,#sgTabIn[hidden],#sgTabOut[hidden]{display:none!important}

/* chat menu drawer */
#chatMenuDropdown{display:none!important}
.lvcs-wrap{position:fixed;inset:0;z-index:100001;background:rgba(0,0,0,.42);display:flex;align-items:flex-end;animation:lvcsIn .18s ease-out}
.lvcs-wrap.out{opacity:0;transition:opacity .2s}
.lvcs-wrap.out .lvcs-sheet{transform:translateY(100%);transition:transform .2s ease-in}
@keyframes lvcsIn{from{opacity:0}to{opacity:1}}
.lvcs-sheet{width:100%;max-height:80vh;overflow:auto;background:var(--card,#fff);color:var(--text,#111);border-radius:22px 22px 0 0;padding:.5rem .9rem calc(1rem + env(safe-area-inset-bottom,0px));animation:lvcsUp .22s cubic-bezier(.2,.9,.3,1)}
@keyframes lvcsUp{from{transform:translateY(100%)}to{transform:none}}
.lvcs-grab{width:42px;height:5px;border-radius:999px;background:color-mix(in srgb,var(--text,#111) 22%,transparent);margin:.2rem auto .7rem}
.lvcs-row{display:flex;align-items:center;gap:.85rem;width:100%;border:0;background:transparent;color:inherit;font-size:1rem;font-weight:600;padding:.7rem .3rem;border-radius:14px;text-align:left;cursor:pointer}
.lvcs-row:active{background:color-mix(in srgb,var(--text,#111) 8%,transparent)}
.lvcs-row.danger{color:#e11d48}
.lvcs-ic{width:2.4rem;height:2.4rem;border-radius:12px;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 16%,transparent);color:var(--c);flex:none}
.lvcs-ic i{color:var(--c)!important;-webkit-text-fill-color:var(--c)!important}

/* ratings in groups of 10 (one open at a time) */
.rv-grp{border-top:1px solid var(--border,rgba(128,128,128,.25))}
.rv-grp-h{display:flex;width:100%;align-items:center;justify-content:space-between;border:0;background:transparent;color:inherit;font-weight:700;padding:.7rem .1rem;cursor:pointer}
.rv-grp-h i{transition:transform .2s}
.rv-grp.open .rv-grp-h i{transform:rotate(180deg)}
.rv-grp:not(.open) .rv-grp-body{display:none}
.rv-more{margin:.6rem 0 .3rem;width:100%}

.sg-info{border:0;background:transparent;color:var(--text-muted,#8a8f98);font-size:1rem;padding:0 .2rem;cursor:pointer;vertical-align:middle}
.sg-info-pop{margin:.4rem 0 0;padding:.65rem .8rem;border-radius:14px;background:var(--card,#fff);border:1px solid var(--border,rgba(128,128,128,.25));box-shadow:0 8px 24px rgba(0,0,0,.14);font-size:.85rem;line-height:1.4;color:var(--text,#111)}
.sg-info-pop[hidden]{display:none}

/* "Latest from" tile: the no-photo picture fills the tile and its icon sits in the middle */
html body #app .storefront-product-mini>.mini-placeholder{display:flex!important;align-items:center;justify-content:center;aspect-ratio:1/1;height:auto!important}
html body #app .storefront-product-mini>.mini-placeholder .lv-noimg{flex:1;height:100%;min-height:100%;justify-content:center}
/* share QR in dark / black mode: one soft slate tile that the code fills edge to edge (no black layers or sharp corners) */
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code{background:#37424d!important;padding:0!important;border-radius:22px!important;overflow:hidden;box-shadow:none!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code canvas,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code canvas{width:100%!important;height:100%!important;display:block;border-radius:22px;filter:invert(1) hue-rotate(180deg) contrast(.6) brightness(1.35)}
/* order details: no gap under the search bar */
html:root:root body #app#app:has(.od-page){margin-top:-1px!important}
/* product form: only the icon choices pick the delivery type (the plain drop-down is hidden); the section has no tinted box */
#prodDeliverySettings>label:first-child,#prodDeliverySettings>#prodDeliveryMode{display:none!important}
.lm-sec.lm-amber{background:transparent!important;border-color:transparent!important;box-shadow:none!important}

/* "Delivery" with its fee underneath (not squeezed beside it) */
html:root:root:root:root:root:root:root body #app#app#app#app#app#app:has(.product-detail-card) .delivery-method-row label{flex-direction:column;align-items:center;justify-content:center;gap:.1rem;text-align:center;line-height:1.2}
html:root:root:root:root:root:root:root body #app#app#app#app#app#app:has(.product-detail-card) .delivery-method-row label .delivery-fee-inline{display:block;font-size:.8em;font-weight:600;opacity:.85}

/* no-photo tile on the shop page: same size as before, the picture icon centred inside it */
html body #app .storefront-product-mini>.mini-placeholder{aspect-ratio:4/3!important;width:100%!important;height:auto!important;position:relative!important;display:block!important;min-height:7rem}
html body #app .storefront-product-mini>.mini-placeholder .lv-noimg{position:absolute!important;inset:0;height:auto!important;min-height:0!important;display:flex;align-items:center;justify-content:center}
/* share QR in dark / black mode: softer slate, less black */
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-card{background:#2c353e!important}
html[data-theme="black"]:root:root body #lvqrSheet .lvqr-card{background:#242c34!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-sheet,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-sheet{background:#1d242b!important}
html[data-theme="dark"]:root:root body #lvqrSheet .lvqr-code,html[data-theme="black"]:root:root body #lvqrSheet .lvqr-code{background:#46535f!important}
/* suggestions (i) is a quiet grey */
.sg-head h2 .sg-info,.sg-head h2 .sg-info i{color:var(--text-muted,#8a8f98)!important;-webkit-text-fill-color:var(--text-muted,#8a8f98)!important}
/* add listing: the extra drop-down bar above the delivery choices is gone */
#prodDeliverySettings .ms-wrap,#prodDeliverySettings>select+.ms-wrap,#prodDeliveryMode+.ms-wrap{display:none!important}

.conv-preview .conv-tk{font-size:.72rem;margin-right:.25rem;color:var(--text-muted,#8a8f98)}
.conv-preview .conv-tk.read{color:#34a0e8}

html[data-theme="dark"]:root:root:root body #lvqrSheet .lvqr-code canvas,html[data-theme="black"]:root:root:root body #lvqrSheet .lvqr-code canvas{filter:invert(1) hue-rotate(180deg) contrast(.6) brightness(1.35)!important}

/* no-photo picture on the product page: a fixed 4:3 area (works on iPhone too), the icon centred inside */
html:root:root:root:root body #app .product-detail-card .product-detail-media .product-img.lv-noimg-page{position:relative!important;height:0!important;padding-bottom:75%!important;aspect-ratio:auto!important;min-height:0!important;overflow:hidden}
html:root:root:root:root body #app .product-detail-card .product-detail-media .product-img.lv-noimg-page>.lv-noimg{position:absolute!important;inset:0;width:100%!important;height:100%!important;display:flex;align-items:center;justify-content:center}
/* no-photo picture in search results */
html body #app .sr-thumb .lv-noimg{width:100%;height:100%;border-radius:inherit}
html body #app .sr-thumb .lv-noimg svg{width:55%;height:55%}
/* initials in the map search suggestions: normal size */
.vmp-sugg .vmp-sg-logo .vd-initials,.vmp-sugg .vmp-sg-logo .vd-initials *{font-size:.9rem!important;line-height:1!important}

/* online / last seen under the shop's name on the product page */
.pd-presence{display:flex;order:0;padding:0!important;margin:.05rem 0 .35rem 2.6rem!important;font-size:.72rem!important;opacity:.7;font-weight:400}
.pd-presence[hidden]{display:none!important}
.service-vendor-info-head .pd-presence{margin-left:0!important}

/* ===== Team, business switcher (tm-): full-screen pages that respect the phone's notch and home bar ===== */
.tm-page{position:fixed;inset:0;z-index:99990;background:var(--bg,#f5f7fb);color:var(--text,#111);overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain}
.tm-wrap{max-width:640px;margin:0 auto;padding:0 16px calc(env(safe-area-inset-bottom,0px) + 96px)}
.tm-top{position:sticky;top:0;z-index:2;display:flex;align-items:center;gap:.75rem;padding:calc(env(safe-area-inset-top,0px) + 12px) 16px 12px;margin:0 -16px 6px;background:color-mix(in srgb,var(--bg,#f5f7fb) 90%,transparent);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.tm-back{width:42px;height:42px;flex:none;border-radius:14px;border:1px solid var(--border,rgba(128,128,128,.25));background:var(--card,#fff);color:var(--text,#111);display:flex;align-items:center;justify-content:center;font-size:.95rem;cursor:pointer}
.tm-title{margin:0;font-size:1.3rem;font-weight:800;letter-spacing:-.015em;line-height:1.15;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tm-sub{margin:.1rem 0 0;font-size:.8rem;color:var(--text-muted,#6b7280)}
.tm-card{background:var(--card,#fff);border:1px solid var(--border,rgba(128,128,128,.16));border-radius:20px;padding:14px;margin-bottom:12px;box-shadow:0 1px 2px rgba(16,24,40,.04),0 10px 28px rgba(16,24,40,.05)}
.tm-hero{display:flex;align-items:center;gap:.85rem;border:0;color:#fff;background:linear-gradient(135deg,#17855a,#25b57a)}
.tm-hero .tm-av{background:rgba(255,255,255,.22);color:#fff}
.tm-hero-name{font-weight:800;font-size:1.08rem;line-height:1.2}
.tm-hero-sub{opacity:.85;font-size:.82rem;margin-top:.1rem}
.tm-av{width:44px;height:44px;flex:none;border-radius:50%;background:linear-gradient(135deg,#1f8a5b,#34c38a);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1.05rem}
.tm-row{display:flex;align-items:center;gap:.75rem}
.tm-grow{flex:1;min-width:0}
.tm-name{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tm-chip{display:inline-flex;align-items:center;gap:.3rem;padding:.12rem .55rem;border-radius:999px;font-size:.72rem;font-weight:700;background:rgba(31,138,91,.14);color:#1f8a5b}
.tm-chip.amber{background:rgba(245,158,11,.18);color:#b45309}
.tm-chip.blue{background:rgba(59,130,246,.15);color:#2563eb}
.tm-chip.grey{background:rgba(128,128,128,.16);color:var(--text-muted,#6b7280)}
.tm-seg{display:flex;gap:4px;padding:4px;border-radius:16px;background:rgba(128,128,128,.14);margin:2px 0 14px}
.tm-seg button{flex:1;border:0;border-radius:12px;padding:.6rem .4rem;font-weight:700;font-size:.92rem;background:transparent;color:var(--text-muted,#6b7280);cursor:pointer}
.tm-seg button.on{background:var(--card,#fff);color:var(--text,#111);box-shadow:0 1px 4px rgba(16,24,40,.12)}
.tm-btn{display:inline-flex;align-items:center;justify-content:center;gap:.45rem;border:0;border-radius:14px;padding:.8rem 1.1rem;font-weight:700;font-size:.95rem;background:#1f8a5b;color:#fff;cursor:pointer;min-height:46px}
.tm-btn.block{width:100%}
.tm-btn.ghost{background:rgba(31,138,91,.12);color:#1f8a5b}
.tm-btn.danger{background:rgba(220,38,38,.1);color:#dc2626}
.tm-btn.sm{padding:.5rem .8rem;min-height:38px;font-size:.88rem;border-radius:12px}
.tm-btn[disabled]{opacity:.55}
.tm-iconbtn{width:38px;height:38px;border-radius:12px;border:0;background:rgba(128,128,128,.14);color:var(--text-muted,#6b7280);display:flex;align-items:center;justify-content:center;cursor:pointer;flex:none}
.tm-input{width:100%;box-sizing:border-box;border:1px solid var(--border,rgba(128,128,128,.3));border-radius:14px;padding:.85rem 1rem;font-size:1rem;background:var(--input-bg,var(--card,#fff));color:var(--text,#111);outline:none}
.tm-input:focus{border-color:#1f8a5b;box-shadow:0 0 0 3px rgba(31,138,91,.18)}
.tm-label{font-weight:800;font-size:.95rem;margin:0 0 .6rem}
.tm-roles{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:.7rem 0}
.tm-role{border:1.5px solid var(--border,rgba(128,128,128,.3));border-radius:14px;padding:.7rem;text-align:left;background:transparent;color:var(--text,#111);cursor:pointer}
.tm-role b{display:block;font-size:.92rem}
.tm-role span{display:block;font-size:.76rem;color:var(--text-muted,#6b7280);margin-top:.1rem}
.tm-role.on{border-color:#1f8a5b;background:rgba(31,138,91,.1)}
.tm-empty{text-align:center;padding:2rem 1rem;color:var(--text-muted,#6b7280)}
.tm-empty i{font-size:2.2rem;opacity:.45;display:block;margin-bottom:.5rem}
.tm-empty b{display:block;color:var(--text,#111);font-size:1rem;margin-bottom:.15rem}
.tm-err{color:#dc2626;font-size:.85rem;margin:.5rem 0 0}
.tm-money{font-weight:800;font-size:1.05rem}
.tm-meta{display:flex;flex-wrap:wrap;gap:.35rem .6rem;color:var(--text-muted,#6b7280);font-size:.82rem;margin:.35rem 0 .2rem}
.tm-items{font-size:.92rem;margin:.35rem 0 .75rem;line-height:1.35}
.tm-actions{display:flex;gap:.5rem;flex-wrap:wrap}
.tm-actions .tm-btn{flex:1}
.tm-bubble{max-width:82%;padding:.5rem .75rem;border-radius:16px;white-space:pre-wrap;word-break:break-word;line-height:1.35}
.tm-bubble.in{align-self:flex-start;background:rgba(128,128,128,.16);border-bottom-left-radius:6px}
.tm-bubble.out{align-self:flex-end;background:#1f8a5b;color:#fff;border-bottom-right-radius:6px}
.tm-thread{display:flex;flex-direction:column;gap:6px;max-height:58vh;overflow:auto;padding:.3rem 0}
.tm-compose{display:flex;gap:.5rem;margin-top:.7rem}
.tm-compose .tm-input{flex:1;padding:.7rem .9rem}
.tm-unread{background:#1f8a5b;color:#fff;border-radius:999px;min-width:1.4rem;height:1.4rem;padding:0 .4rem;font-size:.76rem;font-weight:700;display:flex;align-items:center;justify-content:center}
/* the floating Levi helper stays out of the way while a team / business page is open */
body:has(.tm-page) .levro-static-rails{display:none!important}

.tm-av{overflow:hidden}
.tm-av img{width:100%;height:100%;object-fit:cover;display:block}

/* heart on the chosen recipient in "Transfer": add to favourites without leaving the screen */
.lw-locked .lw-fav{margin-left:auto;margin-right:.35rem;width:36px;height:36px;border-radius:50%;border:0;background:rgba(128,128,128,.14);color:var(--text-muted,#6b7280);display:flex;align-items:center;justify-content:center;font-size:1rem;cursor:pointer;flex:none}
.lw-locked .lw-fav.on{background:rgba(236,72,153,.14);color:#ec4899}
.lw-locked .lw-fav + #lwChange{margin-left:0}
/* Chat bubbles: WhatsApp-style. The time sits at the bottom-right of the bubble, beside a short message (or just under a
   long one), never wrapping letter by letter, and a text bubble is never narrower than its time. */
html body .chat-page-wrap .chat-bubble:not(.photo-only):not(.lv-stk-only){min-width:4.7rem}
html body .chat-page-wrap .chat-bubble .chat-bubble-text{display:inline;overflow-wrap:anywhere;word-break:normal}
html body .chat-page-wrap .chat-bubble .chat-time{display:inline-flex!important;float:right;width:auto!important;margin:.34rem 0 -.1rem .6rem;white-space:nowrap;flex:none;align-items:center;justify-content:flex-end;gap:.3rem;line-height:1.1}
html body .chat-page-wrap .chat-bubble .chat-time-text{white-space:nowrap;flex:none}
html body .chat-page-wrap .chat-bubble::after{content:"";display:block;clear:both}
html body .chat-page-wrap .chat-bubble .chat-image-attachment ~ .chat-time{margin:.3rem .1rem -.05rem .6rem}
html body .chat-page-wrap .chat-media-group .chat-bubble .chat-time{float:none!important;margin:.15rem .45rem .35rem!important;display:block!important}
html body .chat-page-wrap .chat-media-group .chat-media-group-item:not(:last-child) .chat-time{display:none!important}

/* Offline bar: the header and the page start directly below the red bar instead of sitting under it. The bar covers the
   status-bar area, so the header drops its own top spacing and moves down by the bar's one text row (1.9rem). */
#lvOfflineBar{line-height:1rem;white-space:nowrap;overflow:hidden}
html.lv-offline-on{padding-top:1.9rem}
html.lv-offline-on body > header{top:calc(1.9rem + env(safe-area-inset-top,0px))!important;padding-top:0!important}
html.lv-offline-on #levromartHeaderSearchDock{margin-top:1.9rem!important}

/* "Add your phone number" box: a clean card, a still (never moving) phone icon, a light field and a quiet "I'll do it later" */
#requiredBuyerPhoneModal .lv-phone-card{text-align:center}
#requiredBuyerPhoneModal .lv-phone-ico{width:3.6rem;height:3.6rem;margin:.1rem auto .75rem;border-radius:18px;display:grid;place-items:center;font-size:1.5rem;color:#fff;background:linear-gradient(145deg,#22c55e,#15803d);box-shadow:0 8px 20px rgba(22,163,74,.28);animation:none!important}
#requiredBuyerPhoneModal .lv-phone-ico i{animation:none!important;transform:none!important}
#requiredBuyerPhoneModal .lv-phone-t{margin:0 0 .35rem!important;font-size:1.3rem;font-weight:800;letter-spacing:-.01em}
#requiredBuyerPhoneModal .lv-phone-s{margin:0 0 1rem;font-size:.88rem;line-height:1.45;color:var(--text-muted,#667085)}
#requiredBuyerPhoneModal .error-text{margin:0 0 .7rem;padding:.55rem .7rem;border-radius:12px;font-size:.84rem;line-height:1.35;text-align:left;background:color-mix(in srgb,#ef4444 10%,var(--card));color:#b42318}
