html body .lvpin{max-width:480px;border-radius:28px 28px 0 0;padding:.6rem 1.25rem calc(1rem + env(safe-area-inset-bottom,0px));background:var(--card,#fff);color:var(--text,#0f172a);box-shadow:0 -24px 60px rgba(0,0,0,.35)}
