html body .lvpin-t{margin:.15rem 0 .9rem;text-align:center;font-size:.92rem;font-weight:700;color:var(--lvf-mute)}
html body .lvpin-hero{text-align:center;margin:0 0 1.1rem}
html body .lvpin-hero span{display:block;font-size:.8rem;font-weight:600;color:var(--lvf-mute)}
html body .lvpin-hero b{display:block;margin-top:.15rem;font-size:2.45rem;font-weight:800;letter-spacing:-.035em;line-height:1.1}
html body .lvpin-person{margin:.1rem 0 .7rem}
html body .lvpin-av{width:3.4rem;height:3.4rem}
html body .lvpin-rows{margin:0 0 .5rem;padding:0;border-radius:0;background:none;border-top:1px solid var(--lvf-line)}
html body .lvpin-row{padding:.75rem .1rem;border-bottom:1px solid var(--lvf-line);font-size:.9rem}
