html body .lvpin-s{display:flex;align-items:center;justify-content:center;gap:.4rem;margin:.9rem 0 .6rem;font-size:.82rem;font-weight:600;opacity:1;color:var(--lvf-mute)}
html body .lvpin-s i{font-size:.74rem}
html body .lvpin-dots{gap:.95rem;margin:.2rem 0 .8rem}
html body .lvpin-dots i{width:.85rem;height:.85rem;border:0;background:color-mix(in srgb,var(--text) 22%,transparent)}
html body .lvpin-dots i.on{background:var(--lvf-g);transform:scale(1.12)}
html body .lvpin-keys{max-width:330px;gap:.1rem .5rem}
html body .lvpin-keys button{height:3.5rem;border:0;border-radius:18px;background:transparent;color:var(--text);font-size:1.65rem;font-weight:600;font-family:inherit}
