/* --- the slim banner carousel (Transfer, Withdraw and Transaction history) --- */
html body .lvpc{border-radius:16px;margin:0 0 1rem}
html body .lvpc-slide{min-height:0;padding:.85rem 1rem;gap:.6rem;align-items:center}
html body .lvpc-txt b{font-size:.98rem;letter-spacing:-.01em}
