/* --- Transaction history page --- */
html body .lvwh-page .lwh-filters{gap:.5rem}
html body .lvwh-page .lwh-sel,html body .lvwh-page .lwh-sbtn{border-radius:14px;border:0;background:var(--lvf-fill);box-shadow:none}
html body .lvwh-page .lwh-card{border-radius:22px;border:1px solid var(--lvf-line);background:var(--card);box-shadow:none}
html body .lvwh-page .lw-day{margin:.9rem .2rem .3rem;font-size:.78rem;font-weight:700;color:var(--lvf-mute)}
html body .lvwh-page .lw-list li{padding:.75rem .1rem;border-bottom:1px solid var(--lvf-line)}
html body .lvwh-page .lw-list li:last-child{border-bottom:0}

/* --- receipt picker (Share receipt) --- */
.lv-rc{position:fixed;inset:0;z-index:2147483600;display:flex;align-items:flex-end;justify-content:center;background:rgba(3,8,12,.6);-webkit-backdrop-filter:blur(5px);backdrop-filter:blur(5px)}
.lv-rc-in{width:100%;max-width:520px;max-height:94dvh;overflow:auto;box-sizing:border-box;padding:.55rem 1.1rem calc(1rem + env(safe-area-inset-bottom,0px));border-radius:28px 28px 0 0;background:var(--card,#fff);color:var(--text,#111)}
.lv-rc-grab{display:block;width:2.6rem;height:.3rem;margin:.1rem auto .6rem;border-radius:99px;background:color-mix(in srgb,var(--text) 18%,transparent)}
.lv-rc-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:.6rem}
.lv-rc-h b{font-size:1.2rem;font-weight:800;letter-spacing:-.02em}
.lv-rc-h button{width:2.2rem;height:2.2rem;border:0;border-radius:50%;background:var(--lvf-fill);color:var(--text)}
.lv-rc-prev{position:relative;display:grid;place-items:center;max-height:46dvh;overflow:hidden;border-radius:18px;background:var(--lvf-fill);padding:.6rem}
.lv-rc-prev img{display:block;max-width:100%;max-height:calc(46dvh - 1.2rem);width:auto;height:auto;border-radius:12px;box-shadow:0 10px 30px -12px rgba(0,0,0,.4);transition:opacity .2s}
.lv-rc-spin{position:absolute;font-size:1.6rem;color:var(--lvf-g);animation:lvrcspin .9s linear infinite}
@keyframes lvrcspin{to{transform:rotate(360deg)}}
.lv-rc-looks{display:flex;gap:.55rem;overflow-x:auto;padding:.85rem .1rem .5rem;scrollbar-width:none}
.lv-rc-looks::-webkit-scrollbar{display:none}
.lv-rc-looks button{flex:none;display:flex;flex-direction:column;align-items:center;gap:.3rem;border:0;background:none;color:var(--lvf-mute);font:inherit;font-size:.7rem;font-weight:700}
.lv-rc-looks button i{width:3rem;height:3rem;border-radius:50%;border:3px solid transparent;box-shadow:0 0 0 2px transparent;transition:box-shadow .15s}
.lv-rc-looks button.on{color:var(--text)}
.lv-rc-looks button.on i{box-shadow:0 0 0 2px var(--card),0 0 0 4px var(--lvf-g)}
.lv-rc-acts{display:grid;grid-template-columns:1.25fr 1fr 1fr;gap:.5rem;margin-top:.5rem}
.lv-rc-acts button{display:flex;align-items:center;justify-content:center;gap:.4rem;height:3rem;border:0;border-radius:15px;background:var(--lvf-fill);color:var(--text);font:inherit;font-size:.86rem;font-weight:700}
.lv-rc-acts button.pri{background:var(--lvf-g);color:#fff}

/* --- notification icons: a coloured, slightly raised tile instead of a flat grey circle --- */
html body .notif-type-icon:not(.lv3d-n){width:2.7rem;height:2.7rem;border-radius:15px!important;background:linear-gradient(145deg,color-mix(in srgb,var(--nti,#2563eb) 78%,#fff),var(--nti,#2563eb))!important;box-shadow:0 6px 14px -6px var(--nti,#2563eb),inset 0 1px 0 rgba(255,255,255,.4)}
html body .notif-type-icon:not(.lv3d-n) i{color:#fff!important;font-size:1.05rem!important;filter:drop-shadow(0 1px 1px rgba(0,0,0,.25))}

/* --- Place order: the Levromart mark is bigger and sits closer to the words --- */
html body .btn.pd-place-order{display:inline-flex;align-items:center;justify-content:center;gap:.4rem}
html body .btn.pd-place-order .lv-mark-ico{width:1.7em;height:1.7em;margin:-.15em 0 -.15em -.2em}

/* --- the Orders page: the empty message sits plainly on the page (no card, no glow behind it) --- */
html body .lvo-empty,html body #app .lvo-empty,html body #app#app .orders-empty,html body #app#app .orders-empty-live{background:transparent!important;border:0!important;box-shadow:none!important;border-radius:0!important}
html body #app#app .orders-empty-live::before{display:none!important}
html body .lvo-empty .lvo-empty-ico{background:transparent}

/* --- map: the layers button sits just below the category chips --- */
html:root:root body #app .vmpage .vmp-fabs{top:9.3rem!important}
