html:root:root body .lw-sheet .lw-chips button{width:100%!important;margin:0!important}
html:root:root:root:root:root[data-theme] body #app#app .lvo-empty,html:root:root:root:root:root[data-theme] body #app#app .orders-empty,html:root:root:root:root:root[data-theme] body #app#app .orders-empty-live{background:transparent!important;background-image:none!important;border:0!important;box-shadow:none!important;border-radius:0!important}
html:root:root:root:root:root[data-theme] body #app#app .lvo-empty .lvo-empty-ico{background:transparent!important}
html:root:root:root:root:root body #app#app .lvo-empty,html:root:root:root:root:root body #app#app .orders-empty{background:transparent!important;border:0!important;box-shadow:none!important}
html body .btn.pd-place-order .lv-mark-ico{width:3em;height:3em;margin:-.9em -.2em -.9em -.6em}
/* --- the order countdown (hourglass): a warm, soft panel instead of a plain bordered box --- */
html body .lv-hg{gap:1rem;padding:.8rem 1rem;border-radius:20px;border:1px solid color-mix(in srgb,#f59e0b 30%,transparent);background:linear-gradient(135deg,color-mix(in srgb,#f59e0b 16%,var(--card)),var(--card))}
html body .lv-hg .hg-svg{flex:none;filter:drop-shadow(0 6px 8px rgba(184,107,6,.35))}
html body .lv-hg .hg-left{font-size:1.5rem!important;font-weight:800;letter-spacing:-.02em;color:#d97706}
:root[data-theme="dark"] .lv-hg .hg-left,:root[data-theme="black"] .lv-hg .hg-left{color:#fbbf24}
html body .lv-hg small{font-size:.8rem;line-height:1.35}

/* chat: the jump-to-latest arrow floats on the right just above the message box, like WhatsApp */
html body .lm-chat-down{position:fixed!important;left:auto!important;right:1rem!important;transform:none!important;width:2.8rem;height:2.8rem;z-index:60;border:0;box-shadow:0 6px 18px rgba(0,0,0,.28);background:var(--card)!important;color:var(--primary,#16a34a)!important;font-size:1.05rem}

/* --- admin: student / seller verification sheet --- */
html body .req-lightbox{z-index:2147483647!important}
#lvSvReview .lvsr{border-radius:28px 28px 0 0;padding:.7rem 1.2rem calc(1.2rem + env(safe-area-inset-bottom,0px))}
#lvSvReview .lvsr-h{display:flex;align-items:center;justify-content:space-between;margin:.9rem 0 .8rem}
#lvSvReview .lvsr-h strong{font-size:1.2rem;font-weight:800;letter-spacing:-.02em}
