#lvSvReview .lvsr-grid small{display:block;font-size:.72rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--text-muted,#6b7280)}
#lvSvReview .lvsr-grid b{display:block;margin-top:.15rem;font-size:.98rem}
#lvSvReview .lvsr-ph{display:flex;gap:.6rem;margin:.2rem 0 1rem;overflow-x:auto;scrollbar-width:none}
#lvSvReview .lvsr-ph .req-ph-thumb{flex:none;width:6.4rem;height:6.4rem;border-radius:16px;overflow:hidden;border:0;box-shadow:0 6px 16px -8px rgba(0,0,0,.4)}
#lvSvReview .lvsr-msg{display:flex;align-items:flex-end;gap:.55rem;margin:.2rem 0 1rem}
#lvSvReview .lvsr-msg textarea{flex:1;min-height:2.9rem;max-height:7rem;margin:0;padding:.75rem 1rem;border-radius:22px;border:1.5px solid color-mix(in srgb,var(--text) 14%,transparent);background:var(--card);color:var(--text);font:inherit;font-size:.95rem;resize:none}
#lvSvReview .lvsr-msg textarea:focus{outline:none;border-color:var(--primary,#16a34a)}
#lvSvReview .lvsr-send{flex:none;width:2.9rem;height:2.9rem;min-height:0;margin:0;padding:0;border:0;border-radius:50%;display:grid;place-items:center;background:var(--primary,#16a34a);color:#fff;font-size:1.05rem;box-shadow:0 8px 16px -8px rgba(22,163,74,.8)}
#lvSvReview .lvsr-acts{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:.5rem}
#lvSvReview .lvsr-acts button{height:3rem;border-radius:15px;font-weight:700;font-size:.92rem}

/* --- admin: People page (clean segmented tabs, one tidy toolbar, search without overlap) --- */
html body #app .admin-people-toolbar{display:flex;flex-direction:column;gap:.6rem;margin:0 0 .7rem}
html body #app .admin-people-role-tabs{display:grid;grid-template-columns:1fr 1fr;gap:.25rem;padding:.25rem;border-radius:16px;background:color-mix(in srgb,var(--text) 7%,transparent);border:0;box-shadow:none}
html body #app .admin-people-role-tab{display:flex;align-items:center;justify-content:center;gap:.45rem;height:2.7rem;border:0;border-radius:12px;background:transparent;color:var(--text-muted,#6b7280);font-weight:700;box-shadow:none}
html body #app .admin-people-role-tab.active{background:var(--card);color:var(--text);box-shadow:0 2px 8px rgba(0,0,0,.12)}
html body #app .admin-people-role-tab strong{padding:.05rem .5rem;border-radius:999px;font-size:.78rem;background:color-mix(in srgb,var(--primary,#16a34a) 15%,transparent);color:var(--primary,#16a34a)}
html body #app .admin-people-export-actions{display:flex;gap:.5rem}
html body #app .admin-people-export-actions .btn{flex:1;height:2.6rem;border-radius:13px;font-weight:700;box-shadow:none}
html body #app .admin-people-controls{display:flex;gap:.5rem;align-items:center;margin:0 0 .8rem}
html body #app .admin-people-search-wrap{position:relative;flex:1;min-width:0}
