html body #app .admin-people-search-wrap input{width:100%;height:2.9rem;box-sizing:border-box;padding:0 1rem 0 2.6rem;border-radius:15px;border:0;background:color-mix(in srgb,var(--text) 7%,transparent);color:var(--text)}
html body #app .admin-people-sort{display:flex;align-items:center;gap:.3rem;flex:none}
html body #app .admin-people-sort>span{display:none}
html body #app .admin-people-sort select{height:2.9rem;padding:0 .8rem;border-radius:15px;border:0;background:color-mix(in srgb,var(--text) 7%,transparent);color:var(--text);font-weight:600;max-width:9rem}
html body #app .ap-who{display:flex;align-items:center;gap:.6rem}

/* ===================== Vendor statuses ===================== */
.lvst-strip{margin:.2rem 0 .6rem}
.lvst-head{display:flex;align-items:center;justify-content:space-between;padding:0 .2rem .35rem}
.lvst-head b{font-size:.74rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted,#6b7280)}
.lvst-head button{border:0;background:none;color:var(--primary,#16a34a);font-weight:700;font-size:.82rem}
.lvst-row{display:flex;gap:.85rem;overflow-x:auto;padding:.2rem .1rem .5rem;scrollbar-width:none}
.lvst-row::-webkit-scrollbar{display:none}
.lvst-item{flex:none;width:4.4rem;text-align:center}
.lvst-item>span{display:block;margin-top:.3rem;font-size:.7rem;color:var(--text-muted,#6b7280);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lvst-ring{position:relative;width:4.1rem;height:4.1rem;margin:0 auto;padding:3px;border-radius:50%;background:color-mix(in srgb,var(--text) 14%,transparent);display:grid;place-items:center}
.lvst-ring.live{background:conic-gradient(#22c55e,#a3e635,#22c55e)}
.lvst-ring.seen{background:color-mix(in srgb,var(--text) 16%,transparent)}
.lvst-hit{display:block;width:100%;height:100%;padding:0;border:0;background:none;border-radius:50%}
.lvst-av{display:grid;place-items:center;width:100%;height:100%;border-radius:50%;overflow:hidden;border:3px solid var(--bg,#fff);background:color-mix(in srgb,var(--primary,#16a34a) 16%,var(--card));color:var(--primary,#16a34a);font-weight:800;box-sizing:border-box;position:relative}
.lvst-av img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.lvst-av.sm{width:2.5rem;height:2.5rem;border-color:#fff}
.lvst-plus{position:absolute;right:-.15rem;bottom:-.15rem;width:1.5rem;height:1.5rem;border-radius:50%;border:2px solid var(--bg,#fff);background:var(--primary,#16a34a);color:#fff;font-size:.65rem;display:grid;place-items:center;padding:0}
.lvst-li,.lvst-me{display:flex;align-items:center;gap:.85rem;width:100%;box-sizing:border-box;padding:.65rem .2rem;border:0;background:none;color:inherit;text-align:left;font:inherit}
.lvst-li .lvst-ring,.lvst-me .lvst-ring{margin:0;flex:none}
.lvst-lt{flex:1;min-width:0}.lvst-lt b{display:block;font-size:.98rem}.lvst-lt small{color:var(--text-muted,#6b7280);font-size:.8rem}
.lvst-th{width:2.9rem;height:2.9rem;border-radius:12px;object-fit:cover;flex:none}
.lvst-addbtn{flex:none;border:0;border-radius:999px;padding:.5rem 1rem;background:var(--primary,#16a34a);color:#fff;font-weight:700;font-size:.85rem}
.lvst-v{position:fixed;inset:0;z-index:2147483000;background:#000;color:#fff;overflow:hidden}
.lvst-bg{position:absolute;inset:0;background-size:cover;background-position:center;background-color:#10151a}
.lvst-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.55),transparent 26%,transparent 52%,rgba(0,0,0,.88))}
.lvst-bars{position:absolute;top:max(.8rem,env(safe-area-inset-top));left:.8rem;right:.8rem;display:flex;gap:.25rem}
.lvst-bars i{flex:1;height:3px;border-radius:3px;background:rgba(255,255,255,.35);overflow:hidden;position:relative}
.lvst-bars i.d{background:#fff}
.lvst-bars i.run:after{content:"";position:absolute;inset:0;background:#fff;transform-origin:left;transform:scaleX(0);animation:inherit}
.lvst-bars i.run{animation:none!important}
.lvst-bars i.run:after{animation:lvstbar 6s linear forwards}
@keyframes lvstbar{to{transform:scaleX(1)}}
.lvst-top{position:absolute;top:calc(max(.8rem,env(safe-area-inset-top)) + 1.1rem);left:.9rem;right:.9rem;display:flex;align-items:center;gap:.7rem}
.lvst-top b{display:block;font-size:.98rem}.lvst-top small{opacity:.8;font-size:.78rem}
.lvst-x{margin-left:auto;width:2.4rem;height:2.4rem;border:0;border-radius:50%;background:rgba(0,0,0,.35);color:#fff;font-size:1.1rem}
.lvst-tap{position:absolute;top:5rem;bottom:13rem;width:40%;border:0;background:none}
.lvst-tap.l{left:0}.lvst-tap.r{right:0;width:60%}
.lvst-own{position:absolute;left:1rem;right:1rem;bottom:12.5rem;display:flex;justify-content:space-between;font-size:.85rem}
.lvst-own button{border:0;background:rgba(0,0,0,.4);color:#fff;border-radius:999px;padding:.4rem .8rem;font:inherit}
.lvst-card{position:absolute;left:.9rem;right:.9rem;bottom:calc(1.1rem + env(safe-area-inset-bottom,0px));padding:1rem;border-radius:24px;background:rgba(18,22,28,.74);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);border:1px solid rgba(255,255,255,.12)}
.lvst-card h4{margin:0;font-size:1.1rem}.lvst-cap{margin:0 0 .4rem;font-size:.9rem;opacity:.9}
.lvst-pr{margin:.15rem 0 .8rem;font-size:1.35rem;font-weight:800}.lvst-pr s{opacity:.6;font-size:.95rem;font-weight:600}
.lvst-acts{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.lvst-acts button{height:3rem;border:0;border-radius:15px;background:rgba(255,255,255,.16);color:#fff;font:inherit;font-weight:700}
.lvst-acts button.pri{background:var(--primary,#16a34a)}
.lvst-pick{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}
.lvst-pick button{position:relative;aspect-ratio:1;border:0;border-radius:14px;overflow:hidden;padding:0;background:color-mix(in srgb,var(--text) 8%,transparent);color:var(--text-muted)}
.lvst-pick img{width:100%;height:100%;object-fit:cover}.lvst-pick button.sel{outline:3px solid var(--primary,#16a34a);outline-offset:-3px}
.lvst-prev{position:relative;margin:.9rem 0 .7rem;height:15rem;border-radius:22px;overflow:hidden;background:#111}
.lvst-prev img{width:100%;height:100%;object-fit:cover}.lvst-prev span{position:absolute;left:.7rem;bottom:.7rem;padding:.4rem .8rem;border-radius:12px;background:rgba(0,0,0,.62);color:#fff;font-weight:700;font-size:.85rem}
.lvst-chips{display:flex;gap:.5rem;margin:.6rem 0 .9rem}.lvst-chips button{border:0;padding:.5rem .9rem;border-radius:999px;background:color-mix(in srgb,var(--text) 8%,transparent);color:var(--text);font-weight:700;font-size:.82rem}.lvst-chips button.on{background:color-mix(in srgb,var(--primary,#16a34a) 18%,transparent);color:var(--primary,#16a34a)}
/* --- hourglass: flat glass, a colour that follows the time left, and a little hop every so often --- */
