html:root body #lvTour.lvt-news .lvt-sheet h3,html:root body #lvTour.lvt-news .lvt-body{color:#fff!important}
html:root body #lvTour.lvt-news .lvt-body{color:rgba(255,255,255,.86)!important}
html:root body #lvTour.lvt-news .lvt-says{color:#fbbf24!important;letter-spacing:.12em;text-transform:uppercase;font-weight:900}
html:root body #lvTour.lvt-news .lvt-skip{color:rgba(255,255,255,.75)!important}
html:root body #lvTour.lvt-news .lvt-dot{background:rgba(255,255,255,.28)!important}
html:root body #lvTour.lvt-news .lvt-dot.on{background:#fbbf24!important}
html:root body #lvTour.lvt-news .lvt-pri{background:linear-gradient(135deg,#fde68a,#f59e0b)!important;color:#3b0764!important;font-weight:900;box-shadow:0 12px 22px -12px rgba(245,158,11,.9)!important}
html:root body #lvTour.lvt-news .lvt-ghost{background:rgba(255,255,255,.12)!important;color:#fff!important;border:0!important}
html:root body #lvTour.lvt-news .lvt-hole{box-shadow:0 0 0 9999px rgba(30,10,60,.72),0 0 0 3px #fbbf24,0 0 24px 6px rgba(251,191,36,.55)!important}
.lvst-tick{color:#22c55e;font-size:.78em;margin-left:.2rem;vertical-align:baseline}
.lvu-name .lvst-tick{color:#4ade80}
.vendor-profile-header-avatar.lvst-chat-live{box-shadow:0 0 0 3px var(--card,#fff),0 0 0 6px #22c55e!important}
