.lvu-cap{margin:0 0 .35rem .15rem;font-size:.78rem;font-weight:700;color:var(--text-muted,#6b7280)}
.lvu-ghost{background:transparent!important;border:1.8px dashed color-mix(in srgb,var(--text) 20%,transparent);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.5rem;text-align:center;padding:.6rem;color:color-mix(in srgb,var(--text) 38%,transparent)}
