/* ===== Admin orders ===== */
.aor-tabs{overflow-x:auto;scrollbar-width:none}.aor-tabs .adp-tab{white-space:nowrap}
.aor-tab i.aor-n{font-style:normal;margin-left:.3rem;padding:.05rem .45rem;border-radius:999px;background:color-mix(in srgb,var(--text) 10%,transparent);font-size:.72rem}
.aor-tab.on i.aor-n{background:#16a34a;color:#fff}
.aor-hint{margin:.2rem .2rem .8rem;font-size:.82rem;color:var(--text-muted,#6b7280)}
.aor{border-radius:20px;background:var(--card,#fff);border:1px solid color-mix(in srgb,var(--text) 8%,transparent);margin-bottom:.6rem;overflow:hidden}
.aor.hot{border-color:rgba(234,88,12,.55);box-shadow:0 0 0 3px rgba(234,88,12,.12)}
.aor-top{display:flex;align-items:center;gap:.7rem;width:100%;padding:.75rem .8rem;border:0;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
.aor-ph{flex:none;width:3rem;height:3rem;border-radius:14px;overflow:hidden;background:color-mix(in srgb,var(--text) 8%,transparent);display:grid;place-items:center;color:var(--text-muted,#6b7280)}
.aor-ph img{width:100%;height:100%;object-fit:cover}
.aor-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:.1rem}
.aor-main b{font-size:.98rem}.aor-main small{color:var(--text-muted,#6b7280);font-size:.78rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
