.aor-st{flex:none;font-size:.7rem;font-weight:800;padding:.25rem .6rem;border-radius:999px;background:color-mix(in srgb,var(--text) 8%,transparent)}
.aor-st-pending{background:rgba(234,179,8,.2);color:#a16207}.aor-st-confirmed,.aor-st-completed{background:rgba(22,163,74,.15);color:#15803d}.aor-st-cancelled,.aor-st-disputed{background:rgba(225,29,72,.14);color:#be123c}
