.aor-tot{font-weight:800;border-bottom:0!important}
.aor-acts{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:.8rem}
.aor-btn{display:inline-flex;align-items:center;gap:.4rem;border:0;border-radius:999px;padding:.55rem .95rem;background:color-mix(in srgb,var(--text) 8%,transparent);color:var(--text);font:inherit;font-weight:700;font-size:.8rem;text-decoration:none;cursor:pointer}
.aor-btn.go{background:#16a34a;color:#fff}
/* Updates placeholders: soft colour, a round icon and a gentle shimmer */
html body .lvu-ghost{border:1.5px dashed transparent!important;color:#fff!important;position:relative;overflow:hidden;gap:.55rem}
