/* Updates page: no backdrop behind the top bar; a search bar for updates and shops; a pen for your own updates */
.lv-vd-search,.lv-vd-pen{display:none}
body.lv-vd-bar header,body.lv-vd-bar .header{background:transparent!important;border-bottom:0!important;box-shadow:none!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
body.lv-vd-bar .header-search-row{display:none!important}
