.lvsp-handle{display:block;width:2.4rem;height:4px;border-radius:4px;background:color-mix(in srgb,var(--text) 22%,transparent);margin:.2rem auto .5rem}
.lvsp-card button{display:flex;align-items:center;gap:.9rem;width:100%;padding:.95rem 1rem;border:0;background:transparent;color:inherit;font-size:1rem;font-weight:600;border-radius:12px;cursor:pointer;text-align:left}
